YH_EXAM_BANKS["MGT102-CH3"] = {"id":"MGT102-CH3","short":"الفصل الثالث","version":1,"los":[{"lo":"LO3-1","en":"Describe the various personality traits that affect how managers think, feel, and behave.","ar":"سمات الشخصية اللي تأثّر على المدير"},{"lo":"LO3-2","en":"Explain what values and attitudes are, and describe their impact on managerial action.","ar":"القيم والاتجاهات وأثرها على المدير"},{"lo":"LO3-3","en":"Appreciate how moods and emotions influence all members of an organization.","ar":"المزاج والمشاعر وأثرها على الكل"},{"lo":"LO3-4","en":"Describe the nature of emotional intelligence and its role in management.","ar":"الذكاء العاطفي ودوره في الإدارة"},{"lo":"LO3-5","en":"Define organizational culture, and explain how managers both create and are influenced by organizational culture.","ar":"ثقافة المنظمة: المدير يصنعها وتأثّر عليه"}],"sections":{"MGT102-CH3-S1":{"ar":"سمات الشخصية","en":"Personality Traits"},"MGT102-CH3-S2":{"ar":"القيم والاتجاهات","en":"Values and Attitudes"},"MGT102-CH3-S3":{"ar":"المشاعر والذكاء العاطفي","en":"Moods, Emotions, and Emotional Intelligence"},"MGT102-CH3-S4":{"ar":"ثقافة المنظمة","en":"Organizational Culture"}},"misconceptions":[{"id":"c3.trait-vs-mood","ar":"تحسب سمة الشخصية مؤقتة زي المزاج","explain":"سمات الشخصية `personality traits` هي enduring tendencies، يعني ميول ثابتة تطلع في الشغل وبرّاه. بس هو يختار الخيار اللي يوصفها short-lived أو إنها تتغير من يوم ليوم، وهذا وصف الـ mood مو الـ trait.","fix":"ارجع لبلوك «سمات الشخصية» (Personality Traits) في MGT102-CH3-S1 وركّز على كلمة enduring في الـ EXAM BOX، وبعدين قارنها ببلوك «المزاج والمشاعر» في MGT102-CH3-S3.","sec":"MGT102-CH3-S1","coach":"قل له كلمات وخلّه يرد بسرعة «ثابت» أو «متغيّر»: extraversion، mood، conscientiousness، emotion. وكل ما قال trait اسأله: وش الكلمة في التعريف اللي تثبت إنها ثابتة؟ (enduring)"},{"id":"c3.big5-list","ar":"تخربط في عدد وأسماء الـ Big Five","explain":"الـ Big Five خمس سمات بس: extraversion، negative affectivity، agreeableness، conscientiousness، openness to experience، وكل وحدة continuum من Low لـ High مو نمط أو خانة. هو يدخّل فيها self-esteem أو locus of control أو need for power أو emotional intelligence، أو ينسى إن Figure 3.2 يقيس أربع منها بس (ما فيه negative affectivity).","fix":"ارجع لبلوك «سمات الشخصية الخمسة الكبار» في MGT102-CH3-S1 وافتح Figure 3.1 (الخمس خطوط من Low لـ High) و Figure 3.2، وبعدين دور بطاقات MGT102-CH3-S1 لين يطلّع الخمسة بالترتيب بدون غلط.","sec":"MGT102-CH3-S1","coach":"خلّه يعدّ الخمسة على أصابعه بالإنجليزي وبالترتيب، وبعدين ارمِ عليه أسماء مدسوسة (self-esteem، need for power، emotional intelligence) وخلّه يقول «داخل» أو «برّا» القائمة."},{"id":"c3.big5-defs","ar":"تخلط تعريفات سمات الـ Big Five ببعض","explain":"يركّب التعريف على السمة الغلط: «get along well with other people» هي agreeableness مو extraversion، و«careful, scrupulous, and persevering» هي conscientiousness، و«original, daring, take risks» هي openness to experience. وكمان يحسب الانطوائي (low extraversion) هو نفسه صاحب high negative affectivity، والأولى عن التفاعل الاجتماعي والثانية عن المشاعر السلبية والانتقاد.","fix":"ارجع لبلوك «سمات الشخصية الخمسة الكبار» في MGT102-CH3-S1 واقرأ الـ EXAM BOX لكل سمة وفقرة introvert في صندوق الفخ، وبعدين دور بطاقات MGT102-CH3-S1 بوضع «التعريف ← المصطلح».","sec":"MGT102-CH3-S1","coach":"اقرأ له الكلمة المفتاحية بس (outgoing، scrupulous، daring، get along، distressed) وخلّه يقول السمة خلال ثلاث ثواني. وبعدها اسأله: الانطوائي لازم يكون سلبي المشاعر؟ لازم يقول «لا» ويشرح ليش."},{"id":"c3.one-right-trait","ar":"تحسب في سمة وحدة صح للمدير","explain":"الكتاب يقول no single trait is right or wrong: المدير الانطوائي ممكن ينجح، و low agreeableness ميزة للـ drill sergeant، و low openness to experience ميزة لمدير المكتب المالي في الجامعة الحكومية. هو يختار الخيار اللي يقول السمة لازم تكون عالية عشان تنجح، والاستثناء الوحيد اللي يذكره الكتاب إن conscientiousness مؤشّر جيد للأداء.","fix":"ارجع لبلوك «سمات الشخصية الخمسة الكبار» في MGT102-CH3-S1 واقرأ متى يكون الطرف المنخفض ميزة (drill sergeant والمكتب المالي)، وجملة «ما في سمة صح أو غلط» في صندوق الفخ.","sec":"MGT102-CH3-S1","coach":"اعطه وظيفة (رقيب تدريب عسكري، محاسب يطبّق اللوائح بالحرف، مندوب مبيعات) واسأله: أي سمة يفيده يكون فيها منخفض أو عالي؟ واختم بسؤال: أي سمة أفضل مؤشر للأداء في وظايف كثيرة؟ (conscientiousness)"},{"id":"c3.locus-reversed","ar":"تقلب internal و external locus of control","explain":"internal locus of control يعني يحط مسؤولية مصيره في نفسه، وهذا اللي يربطه الكتاب بالسلوك الأخلاقي وبالمدير الناجح. external يعني يحطها في قوى برّا زي الحظ والناس ويميل ما يتدخل (tend not to intervene)، وهو يبدّل الاثنين في السيناريو أو يربط الأخلاق بالـ external.","fix":"ارجع لبلوك «موقع السيطرة وتقدير الذات» في MGT102-CH3-S1 واقرأ الـ EXAM BOX للتعريفين وحيلة «جوّا = أنا، برّا = الظروف» في صندوق الفخ، وبعدين بطاقات MGT102-CH3-S1.","sec":"MGT102-CH3-S1","coach":"قل له جمل على لسان موظف («رسبت لأن الأسئلة ظالمة»، «ترقّيت لأني تعبت»، «المشكلة مو شغلي، خلّ غيري يحلها») وخلّه يحكم internal ولا external، ويقول الكلمة اللي فضحته."},{"id":"c3.needs-swap","ar":"تبدّل حاجات McClelland الثلاث ومستوياتها الإدارية","explain":"need for achievement = يأدّي مهام صعبة بامتياز ويحب الـ feedback، و need for affiliation = علاقات طيبة وإنه يكون محبوب، و need for power = يتحكم أو يأثّر على الآخرين. هو يبدّل التعريفات أو يقلب المستويات: achievement و power ميزة للـ first-line و middle، و power مهمة خصوصاً للـ upper-level.","fix":"ارجع لبلوك «الحاجة للإنجاز والانتماء والقوة» في MGT102-CH3-S1، اقرأ الـ EXAM BOX ونتايج البحوث عن المستويات، وبعدين بطاقات MGT102-CH3-S1.","sec":"MGT102-CH3-S1","coach":"اوصف له شخص بجملة («يبي الكل يحبه»، «يحط أهداف صعبة ويسأل عن تقييمه»، «يبي يأثّر على قرارات غيره») وخلّه يسمّي الحاجة، وبعدها اسأله: أي حاجة تهم المدير الأعلى بالذات؟ ومين صاحب الحاجات الثلاث؟ (McClelland)"},{"id":"c3.affiliation-asset","ar":"تحسب الحاجة العالية للانتماء ميزة للمدير","explain":"الكتاب يقول high need for affiliation مو دايماً مرغوبة، لأنها تخلي المدير يحاول يكون محبوب بدل ما يدفع للأداء العالي. هو يحطها مع السمات المرغوبة (internal locus of control، high self-esteem، high achievement و power) لأنها تبان شي حلو.","fix":"ارجع لصندوق الفخ في بلوك «الحاجة للإنجاز والانتماء والقوة» في MGT102-CH3-S1 واقرأ خلاصة الكتاب عن المدير اللي يمسك زمام الأمور (take-charge).","sec":"MGT102-CH3-S1","coach":"اسأله: «مدير يبي الكل يحبه، وش يصير لما يجيه قرار صعب؟» وخلّه يجاوب بالعربي، وبعدين يعدّد السمات المرغوبة الأربع بالإنجليزي بدون ما يدخّل affiliation."},{"id":"c3.mbti-vs-disc","ar":"تخلط MBTI و DiSC في الأرقام والأصحاب","explain":"MBTI مبني على Carl Jung، يقيس 4 تفضيلات (introversion/extroversion، sensation/intuition، thinking/feeling، judging/perceiving) ويطلّع 16 نمط. أما DiSC فمبني على William Marston ويوصف 4 أساليب سلوك (dominance، influence، steadiness، conscientiousness)، وهو يبدّل الأسماء أو يعطي DiSC الـ 16 نمط.","fix":"ارجع لبلوك «مقاييس شخصية إضافية» في MGT102-CH3-S1 واقرأ صندوق الفخ (٤ تفضيلات ← ١٦ نمط مقابل ٤ أساليب)، وبعدين بطاقات MGT102-CH3-S1.","sec":"MGT102-CH3-S1","coach":"قل له «MBTI» وخلّه يرد: «Jung، أربعة أزواج، 16 نمط»، وقل «DiSC» وخلّه يفك الحروف الأربعة ويقول «Marston». كرّرها لين يجاوب بدون تفكير."},{"id":"c3.values-vs-attitudes","ar":"تخلط بين القيم والاتجاهات والمزاج","explain":"values تعني وش يبي المدير يحقق وكيف يشوف إنه لازم يتصرف، و attitudes أفكاره ومشاعره عن وظيفته ومنظمته المحددة (a collection of feelings and beliefs)، و moods and emotions كيف يحس فعلياً وهو يشتغل. هو يحط تعريف وحدة على الثانية.","fix":"ارجع لأول بلوك في MGT102-CH3-S2 «القيم والاتجاهات والمزاج والمشاعر» (الثلاث عدسات)، وبعدين بطاقات MGT102-CH3-S2.","sec":"MGT102-CH3-S2","coach":"اسأله ثلاث أسئلة وخلّه يقول أي عدسة تجاوب عليها: «وش تبي تحقق في حياتك؟» (value)، «وش رأيك في وظيفتك؟» (attitude)، «كيف تحس الحين؟» (mood)."},{"id":"c3.terminal-vs-instrumental","ar":"تقلب القيمة الغائية والوسيلية","explain":"terminal value هدف أو غاية مدى الحياة (a sense of accomplishment، equality، self-esteem)، و instrumental value نمط سلوك تمشي عليه (ambitious، open-minded، competent، responsible، self-disciplined). هو يقلبهم، أو ينسى إن Rokeach حدد 18 من كل نوع (18 + 18) وتترتب من 1 وهو الأهم.","fix":"ارجع لبلوك «القيم: الغائية والوسيلية» في MGT102-CH3-S2 واقرأ الـ EXAM BOX وحيلة «terminal = المحطة الأخيرة = الهدف»، وبعدين بطاقات MGT102-CH3-S2.","sec":"MGT102-CH3-S2","coach":"قل له قيمة من أمثلة الكتاب (equality، ambitious، responsible، a sense of accomplishment) وخلّه يقول «غاية» ولا «طريقة»، وبعدين اسأله: كم قيمة عند Rokeach من كل نوع؟ (18 و 18)"},{"id":"c3.norms-formal","ar":"تحسب الأعراف قواعد رسمية مكتوبة","explain":"norms هي unwritten, informal codes of conduct تحدد كيف تتصرف في مواقف معيّنة. هو يختار «written, formal rules» أو يخلطها بالـ ceremonies and rites (وهي formal events)، أو يقلب الاتجاه ويقول الأعراف هي اللي تطلّع القيم الغائية، والصح إن terminal values تؤدي للـ norms.","fix":"ارجع لتعريف norms في بلوك «القيم: الغائية والوسيلية» في MGT102-CH3-S2، وبعدين صندوق الفخ في بلوك «دور القيم والأعراف في الثقافة» في MGT102-CH3-S4.","sec":"MGT102-CH3-S2","coach":"اسأله: «اللبس الرسمي مكتوب في لائحة الشركة»، هذا norm؟ و«الكل يسكت لما المدير يتكلم وما أحد قال لهم»، هذا وش؟ وخلّه يفرّق بين norm و policy و rite."},{"id":"c3.satisfaction-vs-commitment","ar":"تخلط الرضا الوظيفي بالالتزام التنظيمي","explain":"التعريفين يبدون بنفس الكلام «The collection of feelings and beliefs that managers have about…» والفرق في آخرهم: their current jobs هي job satisfaction، و their organization as a whole هي organizational commitment. هو يقرأ أول التعريف ويختار بسرعة.","fix":"ارجع لبلوكي «الاتجاهات والرضا الوظيفي» و«الالتزام التنظيمي» في MGT102-CH3-S2 وقارن الـ EXAM BOX حقهم سطر بسطر، وبعدين بطاقات MGT102-CH3-S2.","sec":"MGT102-CH3-S2","coach":"قل له مواقف قصيرة («يحب مهامه وراتبه وزملاءه»، «فخور بالشركة ويدافع عنها قدام الناس») وخلّه يقول job ولا organization، وبعدها خلّه يكمّل نهاية التعريفين بالإنجليزي من راسه."},{"id":"c3.ocb-required","ar":"تحسب سلوكيات المواطنة التنظيمية مطلوبة من الموظف","explain":"OCBs هي behaviors that are not required بس تساهم في efficiency و effectiveness و competitive advantage، يعني فوق الواجب (above and beyond the call of duty). هو يختار الخيار اللي يقول required أو يحسبها جزء من الوصف الوظيفي.","fix":"ارجع لبلوك «الاتجاهات والرضا الوظيفي» في MGT102-CH3-S2، اقرأ الـ EXAM BOX حق OCBs وصندوق الفخ، وبعدين بطاقات MGT102-CH3-S2.","sec":"MGT102-CH3-S2","coach":"اعطه أمثلة («جلس ساعة زيادة يساعد زميله وما أحد طلب منه»، «سلّم تقريره الأسبوعي المطلوب») وخلّه يقول OCB ولا لا، واسأله: وش الكلمتين في التعريف اللي تفرق؟ (not required)"},{"id":"c3.manager-roles","ar":"تربط الالتزام والذكاء العاطفي بأدوار مدير غلط","explain":"الكتاب يقول organizational commitment يساعد المدير في دور figurehead و spokesperson، و emotional intelligence يساعده في الأدوار interpersonal (figurehead، leader، liaison). هو يختار أدوار ثانية من الفصل الأول زي monitor أو negotiator أو resource allocator.","fix":"ارجع لصندوق الفخ في بلوك «الالتزام التنظيمي» في MGT102-CH3-S2 وبلوك «الذكاء العاطفي» في MGT102-CH3-S3، وراجع أدوار المدير من الفصل الأول.","sec":"MGT102-CH3-S2","coach":"قل له «commitment» وخلّه يطلّع الدورين، وقل «emotional intelligence» وخلّه يطلّع الثلاثة، وبعدين اسأله: أدوار الذكاء العاطفي من أي مجموعة؟ (interpersonal)"},{"id":"c3.mood-vs-emotion","ar":"تقلب تعريف المزاج والمشاعر","explain":"mood هو a feeling or state of mind (أخف وأطول وما له سبب محدد)، و emotions هي intense, relatively short-lived feelings مربوطة مباشرة بسببها. هو يقلب الصفات، أو يقلب الاتجاه، والصح إن الـ emotion تهدأ وتبقى mood أخف، مو العكس.","fix":"ارجع لبلوك «المزاج والمشاعر» في MGT102-CH3-S3 واحفظ الفروق الثلاثة (شدّة · سبب · مدّة) من صندوق الفخ، وبعدين بطاقات MGT102-CH3-S3.","sec":"MGT102-CH3-S3","coach":"اوصف له حالة («عصّب بقوة لما شاف الغلط»، «طول اليوم مزاجه مو رايق») وخلّه يقول mood ولا emotion، وبعدين اسأله: وش الثلاث فروق بينهم؟"},{"id":"c3.negative-mood-bad","ar":"تحسب المزاج السلبي ضار دايماً","explain":"الكتاب يقول المزاج السلبي يخلي الشخص detail-oriented ومركّز على الحقائق، ويقوّي critical thinking و devil's advocacy وأحياناً يعطي أحكام أدق، والإبداع يزيد لما يعيش الحالتين في أوقات مختلفة. هو يختار «الإيجابي بس اللي يفيد» أو «السلبي يضر دايماً».","fix":"ارجع لبلوك «أثر المزاج والمشاعر على السلوك في المنظمة» في MGT102-CH3-S3 واقرأ صندوق الفخ «المزاج السلبي مو كله شر».","sec":"MGT102-CH3-S3","coach":"اسأله: «مدير مزاجه سيئ ويراجع عقد مهم، وش الشي الزين اللي ممكن يطلع منه؟» ولازم يقول: يركّز على التفاصيل والحقائق. وبعدين اسأله متى يكون الإبداع أعلى."},{"id":"c3.ei-half-def","ar":"تعرّف الذكاء العاطفي بنص التعريف بس","explain":"emotional intelligence هو القدرة إنك تفهم وتدير مزاجك ومشاعرك أنت، ومزاج ومشاعر الناس الثانيين، وهو ability مو personality trait. هو يختار الخيار اللي يوقف عند one's own moods and emotions، أو يسمّيه سمة زي الـ Big Five.","fix":"ارجع لبلوك «الذكاء العاطفي» في MGT102-CH3-S3، اقرأ الـ EXAM BOX وصندوق الفخ (شقّين في التعريف)، وبعدين بطاقات MGT102-CH3-S3.","sec":"MGT102-CH3-S3","coach":"خلّه يقول التعريف بالإنجليزي كامل، وإذا وقف عند «own» قل له «وبعدين؟» لين يكمّل «and the moods and emotions of other people». وبعدين اسأله: هو ability ولا trait؟"},{"id":"c3.ei-components","ar":"تخربط في الأبعاد الأربعة للذكاء العاطفي","explain":"Figure 3.5 يقسم الذكاء العاطفي لأربعة أبعاد: self-emotions appraisal، others-emotions appraisal، use of emotion، regulation of emotion. هو يحط وصف بُعد تحت بُعد ثاني (مثلاً «أهدأ بسرعة لما أعصب» تحت use بدل regulation)، أو يدخّل أبعاد DiSC لأنها بعد أربعة.","fix":"ارجع لبلوك «الذكاء العاطفي» في MGT102-CH3-S3 وافتح Figure 3.5 واقرأ طريقة التصحيح (كل بُعد له ٤ عبارات)، وبعدين بطاقات MGT102-CH3-S3.","sec":"MGT102-CH3-S3","coach":"قل له عبارات من المقياس بالعربي («أعرف ليش أحس كذا»، «أقرأ مشاعر ربعي من تصرفاتهم»، «أحفّز نفسي وأحط لي أهداف»، «أهدأ بسرعة لما أعصب») وخلّه يسمّي البُعد بالإنجليزي."},{"id":"c3.ei-culture","ar":"تحسب المشاعر نفسها تختلف بين الثقافات","explain":"إطار Managing Globally يقول المشاعر متشابهة بين الثقافات، واللي يختلف هو التعبير عنها: الأمريكي يبيّن حماسه، والبريطاني يخففه، والصيني يشوفه تباهي، والمدراء الصينيين سجّلوا أعلى في جانب مشاعر الآخرين. هو يختار إن الناس تحس بمشاعر مختلفة، أو يقلب مين سجّل أعلى.","fix":"ارجع لبلوك «الذكاء العاطفي يختلف بين الثقافات» في MGT102-CH3-S3 واقرأ صندوق الفخ (أمثلة الحماس والابتسامة).","sec":"MGT102-CH3-S3","coach":"اسأله: «موظف صيني ما بيّن حماس لمشروعك، يعني ما يهمه؟» ولازم يقول لا، الفرق في التعبير والحل إنك تسأل follow-up questions. وبعدين اسأله: وش تعني الابتسامة في اليابان؟"},{"id":"c3.mood-figure","ar":"تغلط في قراءة مقياس المزاج Figure 3.4","explain":"Figure 3.4 فيه 12 كلمة: 6 للمزاج الإيجابي (active، strong، excited، enthusiastic، peppy، elated) و 6 للسلبي (distressed، scornful، hostile، fearful، nervous، jittery) على سلّم من 5، وهم مقياسين منفصلين مو طرفين لخط واحد. هو يحط كلمة في الجهة الغلط، أو يخلطه بـ Figure 3.2 (40 عبارة) أو Figure 3.5 (16 عبارة على سلّم من 7).","fix":"ارجع لبلوك «المزاج الإيجابي والسلبي» في MGT102-CH3-S3 وافتح Figure 3.4 واقرأ طريقة التصحيح، وبعدين قارن عدد العبارات والسلّم مع Figure 3.2 و Figure 3.5.","sec":"MGT102-CH3-S3","coach":"اقرأ عليه الـ 12 كلمة بالإنجليزي بترتيب عشوائي وخلّه يقول «إيجابي» أو «سلبي» ويترجمها، وركّز على اللي يخربط فيها (scornful، jittery، peppy، elated)."},{"id":"c3.culture-def","ar":"تنقص أو تزوّد مكونات تعريف ثقافة المنظمة","explain":"organizational culture هي the shared set of beliefs, expectations, values, norms, and work routines، يعني خمسة مكونات بس. هو يدخّل rules and regulations أو organizational structure أو personality traits، أو يحسب الثقافة القوية يعني «كبيرة»، والصح إنها intense commitment مشترك بالقيم والمعتقدات والروتين.","fix":"ارجع لأول بلوك في MGT102-CH3-S4 «ثقافة المنظمة»، احفظ المكونات الخمسة من الـ EXAM BOX والفرق بين strong و weak، وبعدين بطاقات MGT102-CH3-S4.","sec":"MGT102-CH3-S4","coach":"خلّه يعدّ المكونات الخمسة على أصابعه بالإنجليزي، وبعدين قل له كلمات مدسوسة (structure، rules، work routines، expectations) وخلّه يقول «داخل التعريف» أو «برّا»."},{"id":"c3.asa-framework","ar":"تقلب نموذج ASA أو تغلط في مراحله","explain":"ASA framework حق Benjamin Schneider يشرح كيف الشخصية تأثّر على الثقافة (مو العكس) بثلاث مراحل: attraction و selection و attrition، يعني اللي ما يناسب يطلع. هو يقلب الاتجاه، أو يحسب attrition تدريب، أو ينسب النموذج لـ David Kelley، أو يحسب التشابه الزايد زين دايماً والكتاب يقول يخلي المنظمة تقاوم التغيير.","fix":"ارجع لبلوك «المدير والمؤسِّس ونموذج الجذب والاختيار والتسرّب» في MGT102-CH3-S4 واقرأ الـ EXAM BOX وصندوق الفخ، وبعدين بطاقات MGT102-CH3-S4.","sec":"MGT102-CH3-S4","coach":"خلّه يشرح ASA بقصة مطعم جديد في المدينة بثلاث جمل (مين ينجذب، مين ينختار، مين يطلع)، وبعدين اسأله: وش الخطر لو صار الكل نسخة من بعض؟"},{"id":"c3.transmit-factors","ar":"تغلط في العوامل الأربعة اللي تنقل الثقافة","explain":"Figure 3.6 فيه أربعة عوامل تحفظ الثقافة وتنقلها: values of the founder و socialization و ceremonies and rites و stories and language. هو يدخّل ASA أو norms بينها، أو يربط المثال بالعامل الغلط (Disney University و Fish Camp = socialization، قصص Ray Kroc = stories، «ketchup in their blood» واللبس = language).","fix":"ارجع لبلوك «العوامل الأربعة اللي تحفظ الثقافة وتنقلها» في MGT102-CH3-S4 وافتح Figure 3.6، وبعدين بطاقات MGT102-CH3-S4.","sec":"MGT102-CH3-S4","coach":"اعطه مثال («برنامج تعريفي للموظفين الجدد أسبوع كامل»، «حكاية المؤسس اللي نظّف الحمامات بنفسه»، «كلمة خاصة يستخدمونها داخل الشركة») وخلّه يقول أي عامل من الأربعة، وبعدها يرسم Figure 3.6 من راسه."},{"id":"c3.rites-swap","ar":"تبدّل أنواع الطقوس الثلاثة في Table 3.1","explain":"rite of passage عن كيف تدخل وتتقدم وتطلع (induction and basic training، تتعلم الأعراف وتستدخلها)، و rite of integration تبني روابط مشتركة (office holiday party، والاجتماع السنوي زي Walmart)، و rite of enhancement تقدير علني يقوّي الالتزام (annual awards). هو يبدّل المثال أو الغرض بين الثلاثة.","fix":"ارجع لـ Table 3.1 في بلوك «العوامل الأربعة اللي تحفظ الثقافة وتنقلها» في MGT102-CH3-S4 واحفظ الأعمدة الثلاثة (النوع · المثال · الغرض)، وبعدين بطاقات MGT102-CH3-S4.","sec":"MGT102-CH3-S4","coach":"قل له مناسبات من حياته («أسبوع التدريب الأول في الشغل»، «عشاء تكريم الموظف المثالي»، «فطور رمضان للقسم كله») وخلّه يقول passage أو integration أو enhancement ويبرر بالغرض."},{"id":"c3.innovative-vs-conservative","ar":"تبدّل تصرفات الثقافة المبتكرة والمحافظة","explain":"الثقافة المبتكرة فيها مشاركة المستويات الأدنى في التخطيط، و organic structure مسطّح ولامركزي، و lead by example وتقبّل الفشل؛ والمحافظة فيها formal top-down planning وتسلسل هرمي واضح و management by objectives ومراقبة لصيقة وقواعد واضحة. هو يبدّلهم، أو يحسب المحافظة dysfunctional، والكتاب يقول الاثنين مناسبين حسب الموقف (محطة نووية مقابل IDEO).","fix":"ارجع لبلوكي «دور القيم والأعراف في الثقافة» و«الثقافة والفعل الإداري» في MGT102-CH3-S4 وراجع جدول الوظائف الأربع، وبعدين بطاقات MGT102-CH3-S4.","sec":"MGT102-CH3-S4","coach":"قل له تصرف إداري («كل قرار لازم يمر على المدير العام»، «جرّب ولو فشلت ما عليك»، «MBO ومتابعة كل أسبوع»، «هيكل فيه مستويين بس») وخلّه يقول مبتكرة ولا محافظة، واسأله: المحافظة غلط في محطة نووية؟"},{"id":"c3.culture-two-way","ar":"تحسب المدير يصنع الثقافة وهي ما تأثّر عليه","explain":"LO3-5 يقول managers both create and are influenced by organizational culture: المؤسس والمدير يصنعونها بقيمهم وشخصياتهم، والثقافة ترجع تشكّل قراراته في planning و organizing و leading و controlling وتأثّر على أداء المنظمة. هو يختار اتجاه واحد بس.","fix":"ارجع لبلوك «الثقافة والفعل الإداري» في MGT102-CH3-S4 واقرأ صندوق الفخ (الاتجاه باتجاهين)، وراجع جملة الهدف LO3-5 في رأس الدرس.","sec":"MGT102-CH3-S4","coach":"خلّه يعطيك مثال على مدير غيّر ثقافة شركته ومثال على ثقافة غيّرت تصرف مدير جديد، وإذا جاب واحد بس قل له «والاتجاه الثاني؟»."}],"cases":[{"id":"C3-A","title":"A tough quarter at Marsa Logistics","text":"Faisal manages the Jeddah branch of Marsa Logistics, a company that delivers parcels for online shops. Last quarter, the branch missed its on-time delivery target. Some supervisors blamed port traffic and bad luck, but Faisal disagreed. \"This branch's results depend on the decisions I make, not on luck,\" he told the team calmly, and he began redesigning the delivery routes himself.\n\nFaisal admits that his current job is exhausting and that his pay is only average. Even so, he often tells his friends that he believes in what Marsa is doing, is proud of what the company stands for, and feels very loyal to it.\n\nOn Sunday morning, a major client called to cancel its contract. Faisal felt a sudden, intense anger the moment he put the phone down. About an hour later, once he had decided how to try to win the client back, the anger faded. Still, he stayed slightly gloomy for the rest of the day, even when he was not thinking about the call."},{"id":"C3-B","title":"Building Wasl's culture","text":"Nora founded Wasl, a small app-design studio in Riyadh, in 2021. She is curious and daring, and she enjoys testing risky ideas. When she hired her first designers, adventurous candidates who shared her personality were drawn to the studio, and Nora, who felt drawn to people like herself, chose them. A few careful, rule-loving designers also joined, but most of them resigned within a year because they never felt they fitted in. Today almost everyone at Wasl is adventurous, and the studio's culture is playful and experimental.\n\nEvery Thursday, the whole team shares a long lunch with no agenda, and the chat often turns into new app ideas. Each December, Nora hosts a dinner where she publicly honours the three employees whose apps earned the best user reviews, and their photos are posted on Wasl's social media accounts.\n\nDuring a stressful launch week, Nora noticed she was becoming short-tempered. She realised the cause was her fear of missing the deadline, so she took a short walk to calm down. In the team meeting, she noticed that Majed, a junior designer, was unusually silent, correctly sensed that he was worried about his first big project, and later reassured him privately."}],"questions":[{"n":101,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"term","topic":"personality-traits-definition","stem":"A person's lasting tendencies to feel, think, and act in certain ways, both on and off the job, are called:","options":["Moods","Personality traits","Values","Attitudes"],"answer":1,"why":"personality traits هي enduring tendencies to feel, think, and act in certain ways، والمفتاح كلمة lasting (يعني enduring) وإنها تطلع في الشغل وبرّا الشغل. المزاج يتغيّر بسرعة، أما السمة فثابتة.","wrong":[{"i":0,"mis":"c3.trait-vs-mood","note":"المزاج feeling or state of mind يتغيّر حتى في نفس اليوم، والسؤال يقول lasting يعني ثابت، فهو مو mood."},{"i":2,"mis":"gen.neighbor","note":"القيم قناعات عن أهدافك في الحياة وطريقة تصرفك (القسم الثاني)، مو ميول ثابتة للإحساس والتفكير والتصرف."},{"i":3,"mis":"gen.neighbor","note":"الـ attitude مجموعة مشاعر ومعتقدات عن شغلك ومنظمتك، مو ميل ثابت يوصف شخصيتك كلها."}],"tests":["personality traits","enduring characteristics","tendency","moods","values","attitudes"]},{"n":102,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"term","topic":"agreeableness-definition","stem":"According to the chapter, agreeableness is best defined as:","options":["The tendency to be outgoing, sociable, and energetic","The tendency to be careful, scrupulous, and persevering","The tendency to get along well with other people","The tendency to be original, daring, and open to risks"],"answer":2,"why":"تعريف الكتاب بالحرف: agreeableness = the tendency to get along well with other people، يعني تتفاهم وتنسجم مع الناس، والعالي فيها محبوب ويهتم بالناس. الباقي تعريفات سمات ثانية من الـ Big Five.","wrong":[{"i":0,"mis":"c3.big5-defs","note":"هذا تعريف extraversion، الاثنين فيهم ناس بس extraversion عن الطاقة الاجتماعية، وagreeableness عن الانسجام مع الناس."},{"i":1,"mis":"c3.big5-defs","note":"هذا تعريف conscientiousness، يعني الدقة والحرص والمثابرة، مو التفاهم مع الناس."},{"i":3,"mis":"c3.big5-defs","note":"هذا openness to experience، والجرأة والمخاطرة ما لها دخل بالانسجام مع الآخرين."}],"tests":["agreeableness","extraversion","conscientiousness","openness to experience"]},{"n":103,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"term","topic":"negative-affectivity-definition","stem":"Which trait does the chapter define as the tendency to experience negative emotions and moods, to feel distressed, and to be critical of oneself and others?","options":["Low self-esteem","External locus of control","Low agreeableness","Negative affectivity"],"answer":3,"why":"هذا تعريف negative affectivity بالحرف: مشاعر ومزاج سلبي + ضيق (distressed) + انتقاد للنفس وللآخرين. المفتاح إن التعريف يجمع الثلاث مع بعض.","wrong":[{"i":0,"mis":"gen.neighbor","note":"low self-esteem يعني رأيك في نفسك ضعيف وشاك في قدراتك، بس ما فيه مشاعر سلبية وانتقاد للآخرين."},{"i":1,"mis":"gen.neighbor","note":"external locus عن مين المسؤول عن مصيرك (قوى برّا)، مو عن المزاج السلبي والانتقاد."},{"i":2,"mis":"c3.big5-defs","note":"المنخفض في agreeableness ممكن يكون distrustful وuncooperative، بس التعريف هذا بالحرف حق negative affectivity."}],"tests":["negative affectivity","self-esteem","external locus of control","agreeableness"]},{"n":104,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"figure","topic":"figure-3-1-low-agreeableness","stem":"Look at Figure 3.1. Fahad is a drill sergeant who trains new recruits. He is distrustful of others, unsympathetic, uncooperative, and at times antagonistic. Where on the figure would he most likely be placed?","img":"img/mgt102/figure-3-1.png","options":["Near the low end of dimension III","Near the high end of dimension II","Near the high end of dimension III","Near the low end of dimension IV"],"answer":0,"why":"في Figure 3.1 الخط III هو Agreeableness، وdistrustful وunsympathetic وuncooperative وantagonistic هذي بالحرف أوصاف المنخفض فيها، فمكان فهد قريب من طرف Low في الخط III. والكتاب يقول المستوى المنخفض هذا ممكن يكون asset لـ drill sergeants، وكل سمة continuum مو خانة.","wrong":[{"i":1,"mis":"c3.big5-defs","note":"الخط II هو negative affectivity، وهذي عن المزاج السلبي والضيق وانتقاد النفس، والقصة ما فيها مزاج سلبي، فيها تعامل خصامي مع الناس."},{"i":2,"mis":"gen.reversed","note":"قلبت الخط: العالي في agreeableness محبوب وحنون (affectionate) ويهتم بالناس، وفهد عكس كذا تماماً."},{"i":3,"mis":"c3.big5-defs","note":"الخط IV هو conscientiousness، والمنخفض فيه يبان إنه بلا اتجاه ولا انضباط ذاتي، والقصة ما فيها أي شي عن الانضباط."}],"tests":["figure 3.1","continuum","agreeableness","low agreeableness","drill sergeants","negative affectivity","conscientiousness"]},{"n":105,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"big-five-performance-and-situation","stem":"Which statement about the Big Five personality traits is true according to the chapter?","options":["Effective managers tend to sit at the high end of the extraversion continuum, since quieter managers get less work done.","A low level of openness to experience is a weakness for the manager of a public university's fiscal office.","Recent studies found that agreeableness was more positively related to job performance in competitive environments.","Conscientiousness has been found to be a good predictor of performance in many jobs, including managerial jobs."],"answer":3,"why":"الكتاب يقول conscientiousness a good predictor of performance في وظايف كثيرة ومنها الوظايف الإدارية، وentrepreneurs غالباً عالين فيها لأن مثابرتهم تخليهم يتخطّون العقبات. والقاعدة: no single trait is right or wrong، والمدراء الناجحين في مواقع مختلفة على الـ continuum، فلو مديرك introvert ويبان aloof لا تزعل، هو بطبعه مو اجتماعي.","wrong":[{"i":0,"mis":"c3.one-right-trait","note":"بالعكس، المدراء الناجحين في مواقع مختلفة على الـ continuum، والـ introvert أسلوبه الهادي ممكن يخليه ينجز شغل كثير في وقت قصير، خصوصاً لما الوظيفة ما تحتاج تفاعل اجتماعي كثير."},{"i":1,"mis":"c3.one-right-trait","note":"الكتاب يعطي مدير المكتب المالي في الجامعة مثال إن انخفاض openness ممكن يكون asset، لأن شغله يبي حذر واتباع القواعد مو مخاطرة."},{"i":2,"mis":"gen.reversed","note":"قلبت النتيجة: الدراسات لقت agreeableness less positively related بالأداء في البيئات التنافسية، والـ extraversion هي اللي تنبّأت بالأداء أحسن في الوظايف اللي تحتاج مهارات اجتماعية."}],"tests":["conscientiousness","good predictor of performance","entrepreneurs","extraversion","introverts","successful managers occupy a variety of positions","openness to experience","low openness as an asset","agreeableness","recent studies","no single trait is right or wrong"]},{"n":106,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"tf","topic":"internal-locus-ethics","stem":"According to the chapter, an internal locus of control helps to ensure ethical behavior and decision making in an organization, because people feel accountable for their own actions.","options":["True","False"],"answer":0,"why":"صح. الكتاب يقول internal locus of control يساعد على السلوك والقرارات الأخلاقية، لأن صاحبه يحس إنه accountable و responsible عن تصرفاته. ومثاله Marianne Harrison اللي تشوف نجاح الشركة كله على كتوفها.","wrong":[{"i":1,"mis":"c3.locus-reversed","note":"يمكن حسبت إن الأخلاق تجي من الأنظمة برّا الشخص، بس الكتاب يربطها بالـ internal: اللي يحس إنه مسؤول عن تصرفاته يتصرف بأخلاق."}],"tests":["internal locus of control","external locus of control","locus of control","ethical behavior","accountable"]},{"n":107,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"scenario","topic":"openness-to-experience","stem":"Hessa runs a small design studio in Riyadh. She keeps coming up with original ideas, reads about many different fields, and recently put the studio's savings into a bold new service that no competitor has tried. Which Big Five trait does Hessa show at a high level?","options":["Conscientiousness","Extraversion","Openness to experience","Agreeableness"],"answer":2,"why":"أفكار أصيلة (original) + اهتمامات واسعة (broad interests) + جرأة ومخاطرة (daring, take risks) = تعريف openness to experience كامل. زي Marianne Harrison اللي تدوّر طرق جديدة تنمّي فيها شركتها.","wrong":[{"i":0,"mis":"c3.big5-defs","note":"conscientiousness يعني careful وscrupulous وpersevering، وحصة هنا جريئة وتخاطر، مو حريصة ودقيقة."},{"i":1,"mis":"c3.big5-defs","note":"extraversion عن الاجتماعية والطاقة مع الناس، والقصة ما فيها أي تعامل اجتماعي."},{"i":3,"mis":"c3.big5-defs","note":"agreeableness عن الانسجام مع الناس والاهتمام فيهم، ما لها علاقة بالأفكار الجديدة والمخاطرة."}],"tests":["openness to experience","conscientiousness","extraversion","agreeableness"]},{"n":108,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"figure","topic":"figure-3-2-big-five-measure","stem":"Look at Figure 3.2. The scale gives scores for some of the Big Five personality traits. Which Big Five trait is NOT measured by this scale?","img":"img/mgt102/figure-3-2.png","options":["Agreeableness","Negative affectivity","Openness to experience","Conscientiousness"],"answer":1,"why":"عنوان الشكل نفسه يقول Measures of Extraversion, Agreeableness, Conscientiousness, and Openness to Experience، والتصحيح تحت فيه أربع سمات بس، كل وحدة مجموع 10 items. الناقصة negative affectivity، ما لها ولا item.","wrong":[{"i":0,"mis":"gen.detail","note":"agreeableness موجودة في العنوان وفي التصحيح: مجموع items 1, 4, 8, 12... فهي مقاسة."},{"i":2,"mis":"gen.detail","note":"openness to experience موجودة في العنوان وفي التصحيح (items 2, 7, 11...)، فهي مقاسة."},{"i":3,"mis":"gen.detail","note":"conscientiousness موجودة في عنوان الشكل وفي التصحيح (items 3, 5, 10, 13, 17...)، فهي مقاسة. الوحيدة اللي ما لها items هي negative affectivity."}],"tests":["figure 3.2","negative affectivity","extraversion","agreeableness","conscientiousness","openness to experience"]},{"n":109,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"list","topic":"big-five-list","stem":"Which of the following lists the Big Five personality traits?","options":["Extraversion, internal locus of control, agreeableness, conscientiousness, openness to experience","Dominance, influence, steadiness, conscientiousness, openness to experience","Extraversion, negative affectivity, agreeableness, conscientiousness, openness to experience","Extraversion, negative affectivity, agreeableness, need for achievement, openness to experience"],"answer":2,"why":"الخمسة: extraversion, negative affectivity, agreeableness, conscientiousness, openness to experience. أي اسم من برّا (locus of control، need for achievement، أو حروف DiSC) يخرّب القائمة.","wrong":[{"i":0,"mis":"c3.big5-list","note":"locus of control من «السمات الثانية» برّا الـ Big Five، وراحت مكانها negative affectivity."},{"i":1,"mis":"gen.neighbor","note":"dominance وinfluence وsteadiness هذي أبعاد DiSC حق Marston، بس conscientiousness مشتركة بينهم فتلخبطك."},{"i":3,"mis":"c3.big5-list","note":"need for achievement من حاجات McClelland الثلاث، مو من الخمس الكبار، وراحت مكانها conscientiousness."}],"tests":["big five personality traits","extraversion","negative affectivity","agreeableness","conscientiousness","openness to experience","locus of control","need for achievement","disc inventory profile"]},{"n":110,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"term","topic":"self-esteem-definition","stem":"In the chapter, self-esteem is the degree to which people:","options":["feel good about themselves and their capabilities","locate responsibility for their own fate within themselves","desire to perform challenging tasks well and meet personal standards for excellence","want to control or influence the people around them"],"answer":0,"why":"self-esteem = the degree to which people feel good about themselves and their capabilities. العالي يشوف نفسه competent وdeserving، والمنخفض رأيه في نفسه ضعيف ويشك إنه يقدر ينجح، والبحوث تقول الناس تختار أنشطة وأهداف تناسب مستوى تقديرها لذاتها.","wrong":[{"i":1,"mis":"gen.neighbor","note":"هذا internal locus of control: مين المسؤول عن مصيرك، مو قد إيش تحس إنك زين وقادر."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف need for achievement حق McClelland، رغبة في الإنجاز مو شعورك تجاه نفسك."},{"i":3,"mis":"gen.neighbor","note":"هذا need for power: تبي تتحكم أو تأثّر في غيرك، مو تقديرك لنفسك."}],"tests":["self-esteem","low self-esteem","internal locus of control","need for achievement","need for power"]},{"n":111,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"scenario","topic":"external-locus-of-control","stem":"Faisal supervises a delivery branch of a logistics firm in Jeddah. He is confident in his own skills, but when deliveries run late he says the results are decided by traffic, luck, and head office, and that his own actions make little difference. So he does not step in to fix the problem and leaves it to someone else. Which trait does Faisal show?","options":["Internal locus of control","External locus of control","Low self-esteem","High negative affectivity"],"answer":1,"why":"يرمي النتيجة على قوى خارجية (الزحمة والحظ والإدارة) ويشوف إن تصرفاته ما تفرق، وما يتدخّل ويترك المشكلة لغيره = external locus of control. وعلامته المميزة tend not to intervene.","wrong":[{"i":0,"mis":"c3.locus-reversed","note":"internal بالعكس: صاحبه يشوف تصرفاته هي اللي تحدد النتايج ويتدخّل، وفيصل يرمي المسؤولية على برّا."},{"i":2,"mis":"gen.neighbor","note":"القصة تقول إنه واثق من مهاراته، فمو low self-esteem، المشكلة في وين يحط المسؤولية."},{"i":3,"mis":"gen.neighbor","note":"ما فيه غضب ولا ضيق ولا انتقاد لنفسه وللناس، هو بس يحط المسؤولية على قوى خارجية."}],"tests":["locus of control","external locus of control","internal locus of control","self-esteem","negative affectivity"]},{"n":112,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"scenario","topic":"need-for-achievement","stem":"Noura manages a pharmacy branch in Riyadh. What drives her most is doing difficult tasks well and reaching her own standard of excellence. She sets clear goals for herself every month and asks her regional manager for regular feedback on her performance. Which of the following is high in Noura?","options":["Need for affiliation","Need for power","Openness to experience","Need for achievement"],"answer":3,"why":"رغبة قوية تسوّي المهام الصعبة صح وتوصل معاييرك الشخصية للتميّز = need for achievement. والكتاب يضيف إن أصحابها often set clear goals ويحبون performance feedback، وهذا اللي تسوّيه نورة بالضبط.","wrong":[{"i":0,"mis":"c3.needs-swap","note":"affiliation عن العلاقات الطيبة وإنك تكون محبوب، ونورة ما همّها إن الناس يحبونها، همّها الإنجاز."},{"i":1,"mis":"c3.needs-swap","note":"power يعني تبي تتحكم أو تأثّر في غيرك، ونورة تنافس نفسها ومعاييرها مو تتحكم في أحد."},{"i":2,"mis":"gen.neighbor","note":"openness عن الأفكار الأصيلة والجرأة والمخاطرة، والقصة عن أهداف واضحة وfeedback."}],"tests":["need for achievement","performance feedback","need for affiliation","need for power","openness to experience"]},{"n":113,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"scenario","topic":"need-for-affiliation-in-managers","stem":"Khalid manages a busy café in Madinah. Being liked by his staff matters to him more than anything else at work, and he spends much of his time making sure everyone on the team gets along. Which need is high in Khalid, and what does research in the chapter say about a high level of it in managers?","options":["Need for affiliation; a high level can be an asset for first-line and middle managers","Need for power; a high level can make managers try too hard to be liked by others","Need for affiliation; a high level can make managers try too hard to be liked by others","Need for power; a high level can be an asset for first-line and middle managers"],"answer":2,"why":"خالد همّه يكون محبوب وإن فريقه يتفاهمون مع بعض = need for affiliation. والكتاب يقول الحاجة العالية لها may not always be desirable في المدراء، لأنها ممكن تخليهم يحاولون بزيادة يكونون محبوبين بدل ما يرفعون الأداء.","wrong":[{"i":0,"mis":"c3.affiliation-asset","note":"عرفت الحاجة صح بس قلبت الحكم: الـ asset للمستوى الأول والأوسط هي achievement وpower، أما affiliation العالية فمو دايماً مرغوبة في المدير."},{"i":1,"mis":"c3.needs-swap","note":"الحكم هذا حق affiliation مو power، والـ power يعني تبي تتحكم أو تأثّر في غيرك، وخالد ما يبي كذا."},{"i":3,"mis":"c3.needs-swap","note":"صحيح إن power العالية asset للمستوى الأول والأوسط، بس خالد ما يبي يتحكم في أحد، همّه يكون محبوب."}],"tests":["need for affiliation","need for power","first-line and middle managers"]},{"n":114,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"take-charge-desirable-traits","stem":"The chapter says that, taken together, certain desirable traits suggest managers need to be take-charge people. Which of the following is NOT one of those desirable traits?","options":["An internal locus of control","High self-esteem","A high need for power","A high need for affiliation"],"answer":3,"why":"الصفات المرغوبة اللي تخلي المدير take-charge: internal locus of control + high self-esteem + high needs for achievement and power. الـ affiliation العالية مو منها، الكتاب يقول may not always be desirable لأن المدير يحاول بزيادة يكون محبوب.","wrong":[{"i":0,"mis":"c3.locus-reversed","note":"internal locus من الصفات المرغوبة، لأن المدير مسؤول عن اللي يصير في المنظمة وعن أخلاقياتها ولازم يحس إنه يقدر يفرق، لا تقلبها مع external."},{"i":1,"mis":"gen.detail","note":"high self-esteem منها، تساعده يحط معايير عالية ويثبت عليها، وتدفعه في المشاريع الصعبة، وتعطيه الثقة يتخذ القرارات وينفّذها."},{"i":2,"mis":"c3.needs-swap","note":"power العالية منها، وهي مهمة بالذات للمدراء في المستويات العليا، ودراسة لقت إن رؤساء أمريكا اللي عندهم power عالية كانوا فعّالين بشكل خاص."}],"tests":["take-charge people","internal locus of control","self-esteem","need for affiliation","need for power","need for achievement","upper-level managers","u.s. presidents"]},{"n":115,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"people","topic":"psychologists-matched","stem":"Which psychologist is correctly matched with the work that the chapter links to him?","options":["Carl Jung — the DiSC Inventory Profile used by many companies","William Marston — the Myers–Briggs Type Indicator of personality","Milton Rokeach — the Big Five traits, from extraversion to openness to experience","David McClelland — the needs for achievement, affiliation, and power"],"answer":3,"why":"David McClelland عالم نفس بحث بتوسّع في الحاجات الثلاث: achievement, affiliation, power، وأغلب بحوثها في أمريكا بس ممكن تنطبق بعد في India وNew Zealand. احفظ كل اسم مع شغله: Jung = MBTI، Marston = DiSC، Rokeach = القيم.","wrong":[{"i":0,"mis":"c3.mbti-vs-disc","note":"Carl Jung نظرياته أساس MBTI مو DiSC، لا تخلط بين الأداتين."},{"i":1,"mis":"c3.mbti-vs-disc","note":"William Marston صاحب DiSC، وMBTI حق Carl Jung، قلبت الأصحاب."},{"i":2,"mis":"gen.theorist","note":"Milton Rokeach حق القيم terminal وinstrumental في القسم الثاني، والكتاب ما ينسب الـ Big Five لأي عالم."}],"tests":["david mcclelland","need for achievement","need for affiliation","need for power","carl jung","william marston","myers-briggs type indicator (mbti)","disc inventory profile"]},{"n":116,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"mbti-vs-disc","stem":"Which statement about the Myers–Briggs Type Indicator (MBTI) is true according to the chapter?","options":["It is the most widely used personality instrument and measures preferences such as thinking versus feeling.","It describes a person's behavioral style in terms of dominance, influence, steadiness, and conscientiousness.","It gives each person a profile of behavioral style, preferred environment, and strategies for effectiveness.","Various combinations of its four preferences result in only four unique personality types."],"answer":0,"why":"MBTI مبني على نظريات Carl Jung، وهو أكثر أداة شخصية استخداماً في العالم، ويقيس أربع تفضيلات: introversion/extroversion وsensation/intuition وthinking/feeling وjudging/perceiving، وتوليفاتها تطلع 16 نمط. أما dominance, influence, steadiness, conscientiousness والـ profile اللي فيه behavioral style وpreferred environment وstrategies for effectiveness فهذي كلها DiSC حق William Marston.","wrong":[{"i":1,"mis":"c3.mbti-vs-disc","note":"هذي حروف DiSC نفسها (Dominance, influence, Steadiness, Conscientiousness)، مو أبعاد MBTI."},{"i":2,"mis":"c3.mbti-vs-disc","note":"هذا اللي يطلع لك من DiSC: profile فيه behavioral style وpreferred environment وstrategies for effectiveness، مو MBTI."},{"i":3,"mis":"gen.detail","note":"الرقم غلط: توليفات التفضيلات الأربعة تطلع 16 نمط شخصية فريد، مو أربعة بس."}],"tests":["myers-briggs type indicator (mbti)","most widely used personality instrument","introversion versus extroversion, sensation versus intuition, thinking versus feeling, judging versus perceiving","16 personality types","disc inventory profile","dominance, influence, steadiness, conscientiousness","behavioral style, preferred environment, strategies for effectiveness"]},{"n":117,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"vocab","topic":"vocab-asset","stem":"In the sentence \"Her fluent Arabic and English were a real asset when the hospital in Riyadh started treating international patients,\" the word asset most nearly means:","options":["Something useful that helps you succeed","Something that causes problems and holds you back","A strong push that makes you act quickly","A natural habit of acting in a certain way"],"answer":0,"why":"asset يعني ميزة أو نقطة قوة تفيدك. والكتاب يستخدمها كثير: low agreeableness ممكن تكون asset لـ drill sergeants، وachievement وpower العالية assets للمدراء في المستوى الأول والأوسط.","wrong":[{"i":1,"mis":"gen.vocab","note":"هذا عكس asset (يعني نقطة ضعف أو عبء)، واللغتين ساعدتها مو عطّلتها."},{"i":2,"mis":"gen.vocab","note":"هذا معنى spur (يدفع ويحفّز)، كلمة ثانية من نفس الدرس."},{"i":3,"mis":"gen.vocab","note":"هذا معنى tendency (ميل أو نزعة)، مو asset."}],"tests":["asset"]},{"n":118,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"vocab","topic":"vocab-intervene","stem":"In the sentence \"When two employees started arguing loudly in front of guests, the hotel manager in AlUla decided to intervene right away,\" the word intervene most nearly means:","options":["To step in and try to change the situation","To stay away and let things continue","To report the problem to someone else later","To judge how good or bad something is"],"answer":0,"why":"intervene يعني تتدخّل عشان توقف شي أو تغيّره. والكتاب يقول اللي عندهم external locus of control tend not to intervene، يتركون المشكلة لغيرهم.","wrong":[{"i":1,"mis":"gen.vocab","note":"هذا عكس intervene، إنك تترك الموضوع يمشي يعني ما تدخّلت."},{"i":2,"mis":"gen.vocab","note":"إنك ترفع المشكلة لغيرك بعدين يعني ما تدخّلت بنفسك، وهذا بالضبط عكس الكلمة."},{"i":3,"mis":"gen.vocab","note":"هذا معنى assess (يقيّم)، كلمة ثانية من الدرس، وintervene يعني تدخل بنفسك عشان توقف الشي."}],"tests":["intervene","external locus of control"]},{"n":119,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"vocab","topic":"vocab-scrupulous","stem":"What does the word \"scrupulous\" mean?","options":["متشائم","دقيق ونزيه","جريء","محافظ"],"answer":1,"why":"scrupulous = دقيق ونزيه، يهتم بأصغر تفصيلة وما يتهاون. وهي من تعريف conscientiousness: careful, scrupulous, and persevering.","wrong":[{"i":0,"mis":"gen.vocab","note":"متشائم هي pessimistic، والكتاب يستخدمها لما يقول المنخفض في negative affectivity أقل تشاؤماً، مو scrupulous."},{"i":2,"mis":"gen.vocab","note":"جريء هي daring، من تعريف openness to experience."},{"i":3,"mis":"gen.vocab","note":"محافظ هي conservative، وصف المنخفض في openness to experience."}],"tests":["scrupulous","conscientiousness"]},{"n":120,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"vocab","topic":"vocab-antagonistic","stem":"What does the word \"antagonistic\" mean?","options":["اجتماعي ومنفتح","مثابر","معادي وخصامي","متضايق"],"answer":2,"why":"antagonistic = معادي أو خصامي، يتعامل مع الناس بحدّة كأنهم خصوم. الكتاب يقول low agreeableness ممكن تكون asset في وظايف تتطلب إن المدير يكون antagonistic زي drill sergeants.","wrong":[{"i":0,"mis":"gen.vocab","note":"اجتماعي ومنفتح هي outgoing، من تعريف extraversion، وتقريباً عكس المعادي."},{"i":1,"mis":"gen.vocab","note":"مثابر هي persevering، من تعريف conscientiousness."},{"i":3,"mis":"gen.vocab","note":"متضايق هي distressed، من تعريف negative affectivity."}],"tests":["antagonistic","agreeableness","drill sergeants"]},{"n":201,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"term","topic":"value-system-definition","stem":"The terminal and instrumental values that together act as guiding principles in a person's life are called:","options":["A terminal value","A set of norms","A value system","An attitude"],"answer":2,"why":"value system هو النوعين مع بعض: terminal + instrumental لما يصيرون مبادئ توجّه حياة الشخص. المفتاح في السؤال إن النوعين مذكورين مع كلمة together، يعني مو قيمة وحدة.","wrong":[{"i":0,"mis":"gen.keyword","note":"شاف كلمة terminal في السؤال واختارها، بس terminal value نوع واحد بس (هدف مدى الحياة)، والسؤال يجمع النوعين."},{"i":1,"mis":"gen.neighbor","note":"norms قواعد سلوك غير مكتوبة تخص مجموعة أو منظمة، مو المبادئ الشخصية اللي توجّه حياة الفرد."},{"i":3,"mis":"c3.values-vs-attitudes","note":"attitude مشاعر ومعتقدات عن وظيفتك ومنظمتك، مو القيم اللي توجّه حياتك كلها."}],"tests":["value system","terminal value","instrumental value"]},{"n":202,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"term","topic":"attitude-definition","stem":"In this chapter, an attitude is defined as:","options":["A feeling or state of mind","A collection of feelings and beliefs","An enduring tendency to feel, think, and act","A personal conviction about ways of behaving"],"answer":1,"why":"تعريف attitude أقصر تعريف في الفصل: A collection of feelings and beliefs، يعني مشاعر ومعتقدات مع بعض. ومنه يطلع أهم اتجاهين: job satisfaction و organizational commitment.","wrong":[{"i":0,"mis":"c3.values-vs-attitudes","note":"هذا تعريف mood من الدرس الجاي، وكلمة feeling تلخبط لأنها موجودة في التعريفين."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف personality traits من الدرس الأول: ميول دائمة (enduring)، مو مشاعر ومعتقدات."},{"i":3,"mis":"c3.values-vs-attitudes","note":"هذا تعريف instrumental value (طريقة تصرّف)، يعني قيمة مو اتجاه."}],"tests":["attitude"]},{"n":203,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"term","topic":"ocb-definition","stem":"According to the textbook, organizational citizenship behaviors (OCBs) are behaviors that are:","options":["required of all members and written into their job descriptions to ensure efficiency and effectiveness","not required of members and add little to the organization's efficiency, effectiveness, or competitive advantage","required of managers only, because managers must go above and beyond the call of duty in their roles","not required of members, but necessary for organizational efficiency, effectiveness, and competitive advantage"],"answer":3,"why":"التعريف فيه نصّين مع بعض: not required (مو مطلوبة منك) + بس necessary للكفاءة والفعالية والميزة التنافسية. عشان كذا الكتاب يسمّيها above and beyond the call of duty.","wrong":[{"i":0,"mis":"c3.ocb-required","note":"أشهر فخ في المفهوم: يحسبها جزء من الوصف الوظيفي، والتعريف يبدأ بـ not required."},{"i":1,"mis":"gen.partial","note":"أخذ نص التعريف (not required) بس قلب النص الثاني: الكتاب يقول ضرورية للكفاءة والفعالية، مو قليلة الفايدة."},{"i":2,"mis":"c3.ocb-required","note":"خلّاها مطلوبة من المدراء، بس هي مو مطلوبة من أي أحد؛ المدير الراضي بس أرجح إنه يسويها."}],"tests":["organizational citizenship behaviors"]},{"n":204,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"term","topic":"commitment-definition","stem":"The collection of feelings and beliefs that managers have about their organization as a whole is called:","options":["Organizational commitment","Job satisfaction","Organizational culture","Organizational citizenship behavior"],"answer":0,"why":"تعريف job satisfaction وتعريف organizational commitment يبدون بنفس الكلام، والفرق في آخر كلمات: organization as a whole = organizational commitment، و current jobs = job satisfaction.","wrong":[{"i":1,"mis":"c3.satisfaction-vs-commitment","note":"أشهر فخ في الفصل: job satisfaction نفس الصياغة بس عن الوظيفة الحالية (current jobs)، مو عن المنظمة ككل."},{"i":2,"mis":"gen.keyword","note":"شاف كلمة organization فاختار الثقافة، بس organizational culture هي القيم والأعراف المشتركة بين الأعضاء، مو مشاعر المدير تجاه منظمته."},{"i":3,"mis":"gen.neighbor","note":"OCBs أفعال فوق الواجب، يعني سلوك مو مشاعر ومعتقدات."}],"tests":["organizational commitment","job satisfaction"]},{"n":205,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"concept","topic":"values-attitudes-moods","stem":"The chapter uses values, attitudes, and moods and emotions to explain how managers experience their jobs as individuals. Which statement matches the textbook?","options":["Values capture managers' thoughts and feelings about their jobs; attitudes describe what they aim to achieve and how they should behave.","Attitudes describe how managers actually feel while managing; moods capture their thoughts and feelings about their jobs and organizations.","Values describe what managers aim to achieve and how they should behave; attitudes capture their thoughts and feelings about their jobs.","Moods describe what managers aim to achieve and how they should behave; values capture how they actually feel while they are managing."],"answer":2,"why":"الكتاب يقسّمها كذا: values = وش يبي يحقق وكيف لازم يتصرف، attitudes = أفكاره ومشاعره عن وظيفته ومنظمته، moods and emotions = كيف يحس فعلاً وهو يدير. الخيار هذا هو الوحيد اللي حط كل واحد في مكانه.","wrong":[{"i":0,"mis":"c3.values-vs-attitudes","note":"قلب الاثنين: الكلام عن الوظيفة هو attitudes، والكلام عن وش تبي تحقق وكيف تتصرف هو values."},{"i":1,"mis":"c3.values-vs-attitudes","note":"قلب الاتجاهات والمزاج: «كيف يحس فعلاً وهو يدير» هذا moods and emotions، و«أفكاره ومشاعره عن وظيفته ومنظمته» هذي attitudes."},{"i":3,"mis":"c3.values-vs-attitudes","note":"قلب القيم والمزاج: وش تبي تحقق وكيف تتصرف هذي values، وكيف تحس فعلاً وأنت تدير هذا moods and emotions."}],"tests":["values","attitude","moods and emotions"]},{"n":206,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"concept","topic":"attitudes-in-context","stem":"Which statement about managers' attitudes at work is true according to the textbook?","options":["Entry-level employees are generally more satisfied with their jobs than the upper managers above them.","Gallup's research finds that burnout rates are lower among managers than among nonmanagement workers.","Working conditions can shape them; high stress and low control can lower satisfaction and commitment.","Restructuring and layoffs tend to raise the job satisfaction of the managers who keep their jobs."],"answer":2,"why":"الكتاب يقول الاتجاهات مو صفة شخصية بحتة: ظروف الشغل تشكّلها (وحتى تختلف من دولة لدولة)، والضغط العالي مع سيطرة قليلة على النتايج يجيبون عدم رضا والتزام منخفض. والخيارات الثانية كلها مقلوبة: الرضا يزيد كل ما طلعت فوق، والـ layoffs تنقّص رضا اللي بقوا، والـ burnout عند المدراء أعلى.","wrong":[{"i":0,"mis":"gen.reversed","note":"عكس العلاقة: الرضا يزيد كل ما طلعت فوق في الـ hierarchy، فالمدراء الكبار عموماً أرضى من الموظفين الجدد."},{"i":1,"mis":"gen.reversed","note":"عكس اللي لقاه Gallup: معدلات الـ burnout عند المدراء أعلى من غير الإداريين، لأن التوقعات منهم مو واضحة وأيامهم مليانة مقاطعات."},{"i":3,"mis":"gen.reversed","note":"صدّق فكرة «اللي بقى في شغله يحمد ربه»، بس الكتاب يقول الـ restructuring والـ layoffs تنقّص رضا المدراء اللي بقوا: يخافون يكونون الجايين، وشغلهم يزيد."}],"tests":["attitudes in context","job satisfaction","organizational commitment","restructuring and layoffs","burnout"]},{"n":207,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"concept","topic":"commitment-roles-and-culture","stem":"Rana is a manager at a hospital in Madinah. She truly believes in its values, is proud of what it stands for, and finds it easy to persuade people inside and outside the hospital of the value of its work. According to the textbook, her organizational commitment is likely to:","options":["help her in her negotiator and resource allocator roles, and lead to a strong organizational culture","help her in her figurehead and spokesperson roles, but have little effect on the organizational culture","help her in her negotiator and resource allocator roles, but have little effect on the organizational culture","help her in her figurehead and spokesperson roles, and lead to a strong organizational culture"],"answer":3,"why":"الكتاب يربط الالتزام التنظيمي بشيئين: يساعد في دور figurehead و spokesperson (أسهل تقنع الناس داخل المنظمة وبرّاها لما تكون مؤمن فيها)، ويؤدي لـ strong organizational culture، خصوصاً لما تؤمن فعلاً بقيم المنظمة. عبارة persuade people inside and outside تفضح الأدوار، والسهم يمشي من الالتزام للثقافة.","wrong":[{"i":0,"mis":"c3.manager-roles","note":"نص الثقافة صح، بس الإقناع ذكّره بالتفاوض؛ الكتاب ربط الالتزام بـ figurehead و spokesperson بالاسم، مو negotiator ولا resource allocator."},{"i":1,"mis":"gen.partial","note":"الأدوار صح، بس الكتاب يقول الالتزام يؤدي لـ strong organizational culture، يعني أثره على الثقافة كبير مو قليل."},{"i":2,"mis":"c3.manager-roles","note":"غلط في النصين: الأدوار اللي ربطها الكتاب بالالتزام هي figurehead و spokesperson، والالتزام يقوّي الثقافة مو أثره قليل."}],"tests":["organizational commitment","figurehead role","spokesperson role","strong organizational culture"]},{"n":208,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"scenario","topic":"terminal-vs-instrumental","stem":"Huda runs a private clinic in Riyadh. The aim that guides her whole life is a sense of accomplishment, and she hopes to leave a lasting contribution by opening a new branch abroad one day. On the way, she always tries to be competent and self-disciplined. In the textbook's terms, her life aim of a sense of accomplishment is:","options":["An instrumental value","A terminal value","A norm","An attitude"],"answer":1,"why":"terminal value = هدف مدى الحياة الشخص يبي يوصله. الإحساس بالإنجاز هو الوجهة اللي تبيها هدى في حياتها، وهو من أمثلة الكتاب للقيم الغائية المهمة للمدراء. أما competent و self-disciplined فهذي طريقة تصرّفها في الطريق (instrumental).","wrong":[{"i":0,"mis":"c3.terminal-vs-instrumental","note":"خلط الهدف بالطريقة: instrumental هي طريقة التصرف (competent و self-disciplined)، أما الإحساس بالإنجاز فهو الهدف نفسه."},{"i":2,"mis":"gen.neighbor","note":"norm قاعدة سلوك غير مكتوبة تخص مجموعة أو منظمة، وهنا الكلام عن هدف شخصي في حياة هدى."},{"i":3,"mis":"c3.values-vs-attitudes","note":"attitude مشاعر ومعتقدات عن وظيفة أو منظمة محددة، والهدف اللي يوجّه حياتها كلها قيمة مو اتجاه."}],"tests":["terminal value","instrumental value"]},{"n":209,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"scenario","topic":"norms","stem":"At a software company in Riyadh, no policy says so, but almost everyone on the teams believes that people should never interrupt a colleague who is presenting. Newcomers soon learn to wait their turn, because most members see this way of acting as important. This shared expectation is best described as:","options":["A norm","An instrumental value","A terminal value","Organizational commitment"],"answer":0,"why":"norm = قاعدة سلوك غير مكتوبة وغير رسمية، تحدد كيف تتصرف في موقف معيّن، ومعظم أعضاء المجموعة يشوفونها مهمة. المفتاح: ما هي مكتوبة في أي policy + الأغلبية يمشون عليها + موقف محدد (لما أحد يعرض).","wrong":[{"i":1,"mis":"gen.neighbor","note":"instrumental value قناعة شخصية عند فرد واحد عن طريقة تصرّفه، أما هنا فقاعدة مشتركة تمشي عليها المجموعة كلها."},{"i":2,"mis":"c3.terminal-vs-instrumental","note":"terminal value هدف مدى الحياة، وإنك ما تقاطع زميلك طريقة تصرّف في موقف، مو هدف حياة."},{"i":3,"mis":"gen.neighbor","note":"organizational commitment مشاعرك ومعتقداتك عن المنظمة ككل (فخر وولاء)، مو قاعدة سلوك."}],"tests":["norms"]},{"n":210,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"scenario","topic":"satisfaction-vs-commitment","stem":"Majed is an accountant at a logistics firm in Jeddah. He likes his daily tasks, feels he is treated fairly, and enjoys his good pay and nice coworkers. However, he is not proud of what the firm stands for and feels little loyalty toward it. Majed's feelings and beliefs show a high level of:","options":["Organizational commitment","Job satisfaction","Organizational citizenship behavior","Negative affectivity"],"answer":1,"why":"يحب مهامه + يحس إنه معامل بإنصاف + راتب حلو وزملاء حلوين = هذي بالضبط صفات job satisfaction العالي عن الوظيفة الحالية. بس ما عنده فخر ولا ولاء للشركة ككل، يعني الـ commitment عنده منخفض.","wrong":[{"i":0,"mis":"c3.satisfaction-vs-commitment","note":"الفخر والولاء للشركة ككل هي علامات commitment، وماجد ما عنده هذي؛ اللي عنده رضا عن وظيفته الحالية بس."},{"i":2,"mis":"gen.neighbor","note":"OCBs أفعال فوق الواجب (زي إنك تتأخر تساعد زميل)، والقصة ما فيها أي فعل زيادة، فيها مشاعره عن وظيفته."},{"i":3,"mis":"gen.neighbor","note":"negative affectivity سمة شخصية (مشاعر سلبية وانتقاد للنفس والناس)، وماجد مبسوط بشغله، وقلّة ولائه للشركة اتجاه مو سمة."}],"tests":["job satisfaction","organizational commitment"]},{"n":211,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"scenario","topic":"burnout","stem":"For months, the staff of a busy call center in Dammam have handled heavy workloads under constant stress. Many now feel completely drained, have stopped caring about their work and speak about it with sarcasm and distrust, and can no longer do their jobs well. According to the textbook, their negative attitudes have turned into:","options":["Turnover","Negative affectivity","Burnout","A negative mood"],"answer":2,"why":"burnout = لما ضغط الشغل يوصل لنقطة الموظف فيها منهك (drained)، ومنفصل عن شغله أو ساخر منه (stopped caring و sarcasm and distrust)، وما عاد يقدر يشتغل بفعالية. الثلاث علامات كلها موجودة في القصة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"turnover يعني الناس تستقيل وتطلع، وممكن يكون نتيجة للـ burnout، بس القصة تقول للحين يشتغلون."},{"i":1,"mis":"gen.neighbor","note":"negative affectivity سمة شخصية دائمة من الـ Big Five، وهنا الحالة جات من ضغط الشغل بعد شهور، مو من شخصيتهم."},{"i":3,"mis":"c3.values-vs-attitudes","note":"التعب ذكّره بالمزاج السلبي، بس المزاج حالة تتغير من يوم ليوم؛ الإنهاك مع السخرية من الشغل وعدم القدرة على الأداء بعد شهور ضغط هذا burnout بالاسم."}],"tests":["burnout"]},{"n":212,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"figure","topic":"figure-3-3-satisfaction-measures","stem":"Job satisfaction can be measured globally (the job in general) or by facets (specific parts of the job, such as pay or coworkers). Look at Figure 3.3. Which statement correctly matches its two measures?","img":"img/mgt102/figure-3-3.png","options":["The Faces Scale measures facets of the present job, while the Minnesota Satisfaction Questionnaire measures the job globally.","The Minnesota Satisfaction Questionnaire measures facets of the present job, while the Faces Scale measures the job globally.","The Minnesota Satisfaction Questionnaire measures commitment to the organization as a whole, while the Faces Scale measures job satisfaction.","Both measures ask workers to rank a list of 18 values from 1, the most important, to 18, the least important."],"answer":1,"why":"اقرأ الشكل: الـ Minnesota فيه 12 عبارة تبدأ بـ On my present job، وكل وحدة عن جزء محدد (facet) زي الراتب والترقية والزملاء. أما الـ Faces Scale فتختار وجه واحد يعبّر عن إحساسك تجاه وظيفتك in general، يعني قياس global.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلب المقياسين: الوجوه عن الوظيفة بشكل عام (global)، والعبارات الـ 12 هي اللي عن الأجزاء المحددة (facets)."},{"i":2,"mis":"c3.satisfaction-vs-commitment","note":"عنوان الشكل نفسه Two Measures of Job Satisfaction، والعبارات تبدأ بـ On my present job، يعني رضا عن الوظيفة مو التزام بالمنظمة."},{"i":3,"mis":"gen.neighbor","note":"ترتيب 18 قيمة من 1 لـ 18 هذا Rokeach والقيم، مو مقاييس الرضا الوظيفي اللي في الشكل."}],"tests":["minnesota satisfaction questionnaire","faces scale","job satisfaction","job facets"]},{"n":213,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"rokeach-18-18","stem":"Milton Rokeach described each person's value system with:","options":["18 values in total, 9 terminal and 9 instrumental, each set ranked from 1 (most important) to 9","16 terminal values and 16 instrumental values, each set ranked from 1 (most important) to 16","18 terminal values and 18 instrumental values, each set ranked from 1 (least important) to 18","18 terminal values and 18 instrumental values, each set ranked from 1 (most important) to 18"],"answer":3,"why":"Rokeach حدّد 18 terminal + 18 instrumental، والشخص يرتّب كل مجموعة من 1 (الأهم كمبدأ يوجّه حياته) إلى 18 (الأقل أهمية). احفظها: 18 و 18، والرقم 1 هو الأهم.","wrong":[{"i":0,"mis":"gen.detail","note":"قسم الـ 18 على النوعين، بس الكتاب يقول 18 لكل نوع، يعني 36 قيمة كلها."},{"i":1,"mis":"gen.detail","note":"16 رقم ثاني من الفصل (أنماط MBTI الـ 16)، مو عدد قيم Rokeach."},{"i":2,"mis":"gen.reversed","note":"الأرقام صح بس قلب الترتيب: 1 هو الأهم مو الأقل أهمية."}],"tests":["milton rokeach","value system","terminal value","instrumental value"]},{"n":214,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"why-job-satisfaction-matters","stem":"According to the textbook, why is it desirable for managers to be satisfied with their jobs?","options":["They are more likely to perform OCBs and more likely to look for new jobs, which brings fresh knowledge into the company.","They are more likely to perform OCBs and less likely to quit, which protects the experience and knowledge they have gained.","They are less likely to perform OCBs, since those behaviors are already required, and less likely to quit their positions.","They are more likely to follow formal written rules and less likely to complain about their pay, which keeps labor costs low."],"answer":1,"why":"الكتاب يقول at least two reasons، وهم: (1) الراضي أرجح يسوي OCBs ويتجاوز التوقعات، (2) أقل احتمال يستقيل. وليش الاستقالة تضر؟ لأن الـ turnover يضيّع الخبرة والمعرفة اللي جمعها المدير عن الشركة والصناعة وبيئة الأعمال.","wrong":[{"i":0,"mis":"gen.reversed","note":"عكس السبب الثاني: اللي دايماً يدوّر فرص جديدة هو المدير غير الراضي، والكتاب يشوف الـ turnover خسارة خبرة مو مكسب."},{"i":2,"mis":"c3.ocb-required","note":"OCBs مو مطلوبة أصلاً، والمدير الراضي أكثر احتمال يسويها مو أقل."},{"i":3,"mis":"gen.detail","note":"الكتاب ما ذكر اتباع القواعد ولا الشكوى من الراتب؛ السببين اللي ذكرهم الكتاب هم OCBs وقلّة الاستقالة."}],"tests":["job satisfaction","organizational citizenship behaviors","turnover"]},{"n":215,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"tf","topic":"job-satisfaction-2009","stem":"During the 2009 global recession, when U.S. unemployment was 10% and the underemployment rate was 17.3%, workers who still had jobs reported record-high levels of job satisfaction.","options":["True","False"],"answer":1,"why":"غلط. ممكن تتوقع اللي عنده وظيفة وقت الأزمة يكون راضي، بس الكتاب يقول this is not necessarily the case: في 2009 الرضا طاح لأدنى مستوى في تاريخ الاستطلاع (45% بس). والـ underemployment يشمل اللي وقّفوا يدوّرون شغل واللي يشتغلون دوام جزئي لأنهم ما لقوا دوام كامل.","wrong":[{"i":0,"mis":"gen.reversed","note":"صدّق الفكرة المنطقية «اللي عنده شغل وقت الأزمة يحمد ربه وراضي»، بس الكتاب قال العكس: الرضا نزل لـ record lows."}],"tests":["job satisfaction","underemployment rate"]},{"n":216,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"vocab","topic":"vocab-prescribe","stem":"In the sentence 'Norms are unwritten, informal rules that prescribe how people should act in particular situations,' the word prescribe most nearly means:","options":["describe what happened before","state what should be done","punish people who break rules","write down in an official form"],"answer":1,"why":"prescribe يعني يحدد لك وش تسوي، زي وصفة الدكتور (prescription). يعني الأعراف تقول لك كيف المفروض تتصرف في الموقف.","wrong":[{"i":0,"mis":"gen.vocab","note":"خلطها بـ describe لأن شكل الكلمتين متشابه، بس describe يوصف، و prescribe يحدد وش تسوي."},{"i":2,"mis":"gen.vocab","note":"العقاب مو جزء من المعنى، الكلمة عن توجيهك وش تسوي، مو عن اللي يصير لو خالفت."},{"i":3,"mis":"c3.norms-formal","note":"الأعراف غير مكتوبة أصلاً (unwritten)، فـ prescribe هنا ما تعني تكتب شي رسمي."}],"tests":["prescribe"]},{"n":217,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"vocab","topic":"vocab-exceed","stem":"In the sentence 'Satisfied managers may be more likely to exceed expectations for their organizations,' the word exceed most nearly means:","options":["fall below","carefully follow","go beyond","clearly explain"],"answer":2,"why":"exceed يعني يتجاوز ويعطي أكثر من المطلوب. وهذي نفس فكرة OCBs: above and beyond the call of duty.","wrong":[{"i":0,"mis":"gen.vocab","note":"عكس المعنى: fall below يعني يقصّر وينزل تحت المطلوب."},{"i":1,"mis":"gen.vocab","note":"follow يعني يمشي على التوقعات بس، و exceed يعني يتعداها ويزيد عليها."},{"i":3,"mis":"gen.vocab","note":"explain يعني يشرح، ما لها علاقة بمعنى الكلمة."}],"tests":["exceed"]},{"n":218,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"vocab","topic":"vocab-conduct","stem":"Rokeach's instrumental values describe the modes of conduct a person prefers. What does the word conduct mean?","options":["هدف / غاية","شعور / إحساس","قانون مكتوب","سلوك / تصرّف"],"answer":3,"why":"conduct يعني طريقة تصرّفك وسلوكك. عشان كذا instrumental value = a mode of conduct = طريقة تصرّف، مو هدف.","wrong":[{"i":0,"mis":"c3.terminal-vs-instrumental","note":"هدف/غاية هذي فكرة terminal value، و conduct عن طريقة التصرف."},{"i":1,"mis":"gen.vocab","note":"الشعور يعني feeling، و conduct فعل وتصرّف مو إحساس."},{"i":2,"mis":"gen.vocab","note":"conduct ما تعني قانون، حتى codes of conduct في تعريف norms غير مكتوبة."}],"tests":["conduct"]},{"n":219,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"vocab","topic":"vocab-loyalty","stem":"Committed managers 'feel a high degree of loyalty toward their organizations.' What does loyalty mean?","options":["رضا","ولاء","طموح","تعاطف"],"answer":1,"why":"loyalty يعني ولاء: تثبت مع المنظمة وما تتركها عند أول مشكلة. وهي من علامات organizational commitment.","wrong":[{"i":0,"mis":"c3.satisfaction-vs-commitment","note":"رضا = satisfaction، كلمة ثانية؛ الولاء علامة الالتزام بالمنظمة مو الرضا عن الوظيفة."},{"i":2,"mis":"gen.vocab","note":"طموح = ambitious، وهي من القيم الوسيلية، مو معنى loyalty."},{"i":3,"mis":"gen.vocab","note":"تعاطف = compassion أو empathy، كلمات ثانية من نفس الدرس."}],"tests":["loyalty"]},{"n":301,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"term","topic":"mood-definition","stem":"How does the textbook define a mood?","options":["Intense, relatively short-lived feelings","A feeling or state of mind","A collection of feelings and beliefs","Enduring tendencies to feel, think, and act"],"answer":1,"why":"الكتاب يقول بالحرف: A mood is a feeling or state of mind. يعني تعريف المزاج قصير وعام. أما Emotions are more intense feelings than moods وهي relatively short-lived، فهذا تعريف الـ emotions. المزاج أخف وأطول ومو مربوط بسبب معيّن، والمشاعر أشد وأقصر ولها سبب واضح، فلا تقلبهم.","wrong":[{"i":0,"mis":"c3.mood-vs-emotion","note":"هذا تعريف الـ emotions، وهي أشد وأقصر من المزاج، فقلبت الاثنين."},{"i":2,"mis":"c3.values-vs-attitudes","note":"هذا تعريف الـ attitude من القسم اللي قبل (a collection of feelings and beliefs)، مو حالة ذهنية."},{"i":3,"mis":"c3.trait-vs-mood","note":"هذا تعريف personality traits، شي ثابت ودايم، والمزاج يتغير من يوم ليوم."}],"tests":["mood","emotions"]},{"n":302,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"term","topic":"positive-mood-feelings","stem":"According to the book, when people are in a positive mood, they feel:","options":["Distressed, fearful, scornful, or hostile","Outgoing, sociable, and energetic","Excited, enthusiastic, active, or elated","Careful, scrupulous, and persevering"],"answer":2,"why":"المزاج الإيجابي = excited, enthusiastic, active, elated. والسلبي = distressed, fearful, scornful, hostile, jittery, nervous. وهذي نفسها كلمات Figure 3.4.","wrong":[{"i":0,"mis":"gen.reversed","note":"هذي مشاعر الـ negative mood، يعني قلبت الإيجابي والسلبي."},{"i":1,"mis":"c3.trait-vs-mood","note":"كلمة energetic قريبة من active فتسحبك، بس هذا تعريف extraversion وهي سمة ثابتة مو مزاج."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف conscientiousness من الـ Big Five، سمة شخصية مو وصف لمزاج."}],"tests":["positive mood","negative mood"]},{"n":303,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"term","topic":"ei-definition","stem":"Which of the following is the textbook's definition of emotional intelligence?","options":["The ability to understand and manage one's own moods and emotions so they do not block good decisions","The tendency to experience negative emotions and moods, to feel distressed, and to be critical of oneself and others","The ability to understand and manage one's own moods and emotions and the moods and emotions of other people","The ability to understand and manage the moods and emotions of employees, customers, and other people"],"answer":2,"why":"تعريف الـ emotional intelligence له شقّين: مزاجك ومشاعرك أنت + مزاج ومشاعر الناس الثانيين، وفعلين: understand و manage. الخيار اللي فيه الشقّين مع بعض هو الصح.","wrong":[{"i":0,"mis":"c3.ei-half-def","note":"هذا نص التعريف بس (مشاعرك أنت)، ونسى شق الناس الثانيين، فهو ناقص."},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف negative affectivity، سمة من الـ Big Five، مو قدرة على فهم المشاعر وإدارتها."},{"i":3,"mis":"c3.ei-half-def","note":"هذا الشق الثاني بس (مشاعر الآخرين)، وناقصه مشاعرك أنت."}],"tests":["emotional intelligence","negative affectivity"]},{"n":304,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"term","topic":"ei-regulation-of-emotion","stem":"One of the four dimensions of emotional intelligence is about managing your own emotions and recovering from emotional upset, such as calming down quickly after becoming very angry. Which dimension is it?","options":["Self-emotions appraisal","Use of emotion","Regulation of emotion","Others-emotions appraisal"],"answer":2,"why":"Regulation of emotion = إنك تضبط مشاعرك وتهدأ بسرعة بعد الزعل. وفي Figure 3.5 عباراتها كلها عن التحكم: control my temper، calm down quickly، good control of my own emotions.","wrong":[{"i":0,"mis":"c3.ei-components","note":"Self-emotions appraisal يعني تعرف وتفهم مشاعرك أنت، مو تتحكم فيها وتهدّيها."},{"i":1,"mis":"c3.ei-components","note":"Use of emotion يعني تستخدم مشاعرك عشان تحفّز نفسك وتوصل لأهدافك، مو تهدّي غضبك."},{"i":3,"mis":"c3.ei-components","note":"Others-emotions appraisal عن فهم مشاعر الناس الثانيين، والسؤال عن مشاعرك أنت."}],"tests":["regulation of emotion","self-emotions appraisal","use of emotion","others-emotions appraisal"]},{"n":305,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"concept","topic":"mood-research-findings","stem":"Which of the following is NOT a research finding about moods and emotions reported in the book?","options":["People in negative moods tend to be more detail-oriented and focused on facts","Brain areas for emotions and moods are especially active in hard personal moral dilemmas","Negative moods tend to lead to more expansive, and even playful, thinking","Critical thinking and devil's advocacy may be promoted by a negative mood"],"answer":2,"why":"التفكير الواسع وحتى المرح (expansive and playful thinking) يجي من المزاج الإيجابي لأنه إشارة إن الأمور ماشية زين، فهذا الخيار قلب الاثنين. والباقي كلها نتايج بحوث في الكتاب: المزاج السلبي يخليك تركز على التفاصيل ويدعم التفكير النقدي و devil's advocacy، وبحث Princeton لقى إن أجزاء الدماغ حقت المشاعر والمزاج تشتغل بقوة لما الناس يحلون معضلات أخلاقية شخصية صعبة.","wrong":[{"i":0,"mis":"gen.reversed","note":"التركيز على التفاصيل والحقائق هو فعلاً أثر المزاج السلبي، لأنه إشارة إن فيه مشكلة تحتاج انتباه، فلا تحسبه للإيجابي."},{"i":1,"mis":"gen.detail","note":"هذا بحث Princeton اللي في الكتاب، ومعناه إن المزاج والمشاعر لهم دور في القرارات الأخلاقية، فهو نتيجة حقيقية مو الجواب."},{"i":3,"mis":"c3.negative-mood-bad","note":"تحسب المزاج السلبي ما يجيب شي زين، بس الكتاب يقول التفكير النقدي و devil's advocacy ممكن يزيدون معه."}],"tests":["negative mood","positive mood","moods as signals","critical thinking","devil's advocacy","ethical decision making","princeton moral dilemmas"]},{"n":306,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"concept","topic":"moods-at-work-findings","stem":"Which statement about moods at work is true according to the book?","options":["People high on negative affectivity are always in a bad mood while at work","A pay raise rarely lifts the mood of people who are low on extraversion","Employees of managers in positive moods may do better work and resign less","Employees prefer to bring unusual ideas to a manager who is in a bad mood"],"answer":2,"why":"الكتاب يقول موظفين المدير اللي يعيش مزاج إيجابي في الشغل ممكن يأدّون أعلى شوي وأقل احتمال إنهم يستقيلون (resign) ويتركون المنظمة. والباقي فخاخ: الـ negative affectivity العالية مو دايماً مزاج سيئ، والزيادة تحط أغلب الناس في مزاج حلو مهما كانت سماتهم، والموظف يجيب فكرته الغريبة للمدير اللي مزاجه حلو ويتجنب اللي مزاجه سيئ جداً.","wrong":[{"i":0,"mis":"gen.absolute","note":"الكتاب قال اللي عندهم negative affectivity عالية أكثر عرضة للمزاج السلبي بس مو دايماً، وكلمة always هي الفخ."},{"i":1,"mis":"c3.trait-vs-mood","note":"تحسب السمة تتحكم في المزاج لحالها، بس الكتاب يقول الزيادة تحط أغلب الناس في مزاج حلو بغض النظر عن سماتهم، واللي منخفضين في extraversion لسا يعيشون مزاج إيجابي."},{"i":3,"mis":"gen.reversed","note":"قلبت العلاقة: الموظف يجيب فكرته الغريبة للمدير لما يحس إن مزاجه حلو، ولما يكون مزاجه سيئ جداً يتجنبونه."}],"tests":["mood","negative affectivity","extraversion","situations and circumstances","positive moods and employee performance and turnover","how managers' moods affect others' responses"]},{"n":307,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"concept","topic":"mood-vs-emotion-differences","stem":"Which statement correctly compares emotions with moods, according to the book?","options":["Emotions are less intense than moods, but they last longer and rarely have a clear cause","Emotions are more intense, often directly linked to their cause, and more short-lived","Emotions are more intense than moods, and they also last longer than moods do","Emotions and moods are equally intense; they differ only in how long they last"],"answer":1,"why":"الفروق ثلاثة: الشدة (الـ emotions أشد)، السبب (غالباً مربوطة مباشرة باللي سبّبها)، والمدة (أقصر). والخيار الصح هو الوحيد اللي جاب الثلاثة بالاتجاه الصح.","wrong":[{"i":0,"mis":"c3.mood-vs-emotion","note":"قلبت الاثنين: الـ mood هو الأخف والأطول، والـ emotion أشد وأقصر ومربوط بسببه."},{"i":2,"mis":"gen.partial","note":"الشدة صح، بس المدة مقلوبة: الـ emotions أقصر عمراً من المزاج، مو أطول."},{"i":3,"mis":"gen.detail","note":"الفرق مو المدة بس، فيه ثلاث فروق: الشدة والارتباط بالسبب والمدة."}],"tests":["mood","emotions","three differences between mood and emotions"]},{"n":308,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"scenario","topic":"emotion-lingers-as-mood","stem":"Huda, a pharmacy manager at a hospital in Riyadh, becomes very angry when she finds that a supplier has sent the wrong medicine. She calls the supplier, the problem is fixed within an hour, and her anger fades. Still, she feels low and irritable for the rest of the day, even though she is no longer thinking about the supplier. In the book's terms, her anger and her feeling for the rest of the day are:","options":["A mood, followed by an emotion","An emotion, followed by a mood","An emotion, followed by an attitude","A personality trait, followed by a mood"],"answer":1,"why":"الغضب كان قوي ومربوط مباشرة بسببه (المورّد) وراح بسرعة، يعني emotion. وبعد ما انحلت المشكلة بقى الشعور على شكل mood أخف، حتى وهي ما تفكر في الحادثة. وهذا كلام الكتاب: الـ emotion ممكن يبقى على شكل mood أقل شدة.","wrong":[{"i":0,"mis":"c3.mood-vs-emotion","note":"قلبت الترتيب: الشي القوي القصير المربوط بسببه هو الـ emotion، وهو اللي يتحول لـ mood أخف، مو العكس."},{"i":2,"mis":"c3.values-vs-attitudes","note":"الـ attitude مجموعة مشاعر ومعتقدات عن الوظيفة أو المنظمة، وهي هنا بس حاسة بضيق عام بقية اليوم."},{"i":3,"mis":"c3.trait-vs-mood","note":"السمة شي ثابت ودايم، وغضبها جا من موقف واحد وراح بعد ساعة، فهو مو سمة."}],"tests":["emotions","mood","emotion lingers as a less intense mood"]},{"n":309,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"scenario","topic":"mood-and-creativity","stem":"At a design studio in Al-Khobar, the team has cheerful weeks after winning new clients and frustrated weeks after losing pitches. The manager welcomes unusual ideas and gives the team time to try them. The studio is known for very creative work. According to recent research in the book, what best explains this?","options":["Their good moods after wins, which gave people energy to try new things","Having good and bad moods at different times, plus support for new ideas","Their bad moods after losses, which pushed people to work harder on ideas","Strong, stable personalities that keep their moods the same all year round"],"answer":1,"why":"البحث الحديث في الكتاب يقول الموظف يكون مبدع أكثر لما يعيش المزاجين (الإيجابي والسلبي) في أوقات مختلفة، ولما بيئة الشغل تدعم الإبداع. والقصة فيها الاثنين: أسابيع فرح وأسابيع إحباط، ومدير يرحّب بالأفكار الغريبة، وكل مزاج لحاله يفسّر نص القصة بس.","wrong":[{"i":0,"mis":"gen.partial","note":"صح إن المزاج الإيجابي ممكن يعزز الإبداع تحت ظروف معيّنة، بس هذا نص الفكرة، والبحث الحديث يقول المزاجين مع بيئة داعمة."},{"i":2,"mis":"gen.partial","note":"صح إن المزاج السلبي ممكن يدفعهم يشتغلون أقوى على أفكارهم، بس هذا بعد نص الفكرة وناقصه المزاج الإيجابي والبيئة الداعمة."},{"i":3,"mis":"c3.trait-vs-mood","note":"المزاج في القصة يتغير مع الظروف (فوز وخسارة)، والكتاب يقول الظروف بعد تحدد المزاج، فمو شخصية ثابتة تخلي المزاج نفسه طول السنة."}],"tests":["creativity","positive mood","negative mood","both mood states","supportive work environment"]},{"n":310,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"scenario","topic":"ei-scenario","stem":"Faisal, a shift supervisor at a logistics company in Jeddah, feels anxious and afraid when a big delivery deadline is suddenly moved up. He stops to understand why he feels this way and calms himself, so the fear does not cloud his choice of plan. He then eases his drivers' worry and energizes them to find creative ways to meet the deadline. Faisal is showing a high level of:","options":["Agreeableness","Negative affectivity","Emotional intelligence","Internal locus of control"],"answer":2,"why":"فيصل فهم خوفه وقلقه وليش جا وضبطه عشان ما يخرب قراره، وبعدين فهم قلق السوّاقين وشحن طاقتهم. هذا الذكاء العاطفي: تفهم وتدير مشاعرك أنت ومشاعر غيرك، والكتاب يقول يخلي المدير يدير الخوف والقلق عشان ما يعيقون القرار، ويشحن طاقة موظفينه ويوقظ إبداعهم.","wrong":[{"i":0,"mis":"gen.neighbor","note":"agreeableness يعني تمشي مع الناس زين، بس هي سمة شخصية ثابتة، والقصة عن قدرة إنك تفهم وتضبط خوفك أنت وقلق غيرك."},{"i":1,"mis":"gen.keyword","note":"كلمة anxious و afraid تسحبك لـ negative affectivity، بس هذي ميل إنك تحس بمشاعر سلبية، مو قدرة إنك تديرها."},{"i":3,"mis":"gen.neighbor","note":"internal locus of control يعني تحس إن مصيرك بيدك، والقصة مو عن مين المسؤول عن النتيجة، هي عن فهم المشاعر وإدارتها."}],"tests":["emotional intelligence","managing fear and anxiety so they do not block decision making","managing others' emotions","energizing employees","awakening employee creativity"]},{"n":311,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"scenario","topic":"ei-across-cultures","stem":"At a team meeting in Riyadh, Nora praises Kenji, a newly hired engineer from Japan, in front of everyone for his personal success on a project. Kenji smiles and looks down. Nora decides the smile means he loved the public praise, so she plans to do it often. According to the book, what should she do?","options":["Keep her plan, since a smile shows happiness and friendliness in every culture","Ask him follow-up questions, since in Japan a smile can cover embarrassment","Decide he is not driven by success, since feelings differ from culture to culture","Keep her plan, since much of Asia values individual success over group harmony"],"answer":1,"why":"الكتاب يقول المشاعر متشابهة بين الثقافات، اللي يختلف هو وش يتعلم الناس يظهرونه: في اليابان الابتسامة كثير تغطي الإحراج أو الزعل، وفي أغلب آسيا انسجام الجماعة أهم من الفرد، فالمدح العلني على نجاح شخصي ممكن يبان غير مناسب. فالمفروض نورة تراجع افتراضها وتسأله أسئلة متابعة وتتعلم الأعراف العاطفية لثقافته.","wrong":[{"i":0,"mis":"gen.absolute","note":"في أمريكا الشمالية الابتسامة تعني ودّ ونية طيبة، وفي شمال أوروبا تعني سعادة بس، وفي اليابان غالباً تغطي إحراج، فمو نفس المعنى في كل الثقافات."},{"i":2,"mis":"c3.ei-culture","note":"الكتاب واضح: feelings are similar across cultures، والاختلاف في التعبير عن المشاعر مو في الإحساس نفسه."},{"i":3,"mis":"gen.reversed","note":"قلبت العلاقة: في أغلب آسيا انسجام الجماعة (group harmony) أهم من الفردية، فالاحتفال العلني بنجاح شخصي ممكن يبان غير مناسب."}],"tests":["emotional intelligence varies by culture","smiling differs by culture","cultural values behind emotional expression","group harmony","feelings are similar across cultures","follow-up questions"]},{"n":312,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"figure","topic":"figure-3-4-scoring","stem":"Look at Figure 3.4. A nurse in Riyadh felt \"quite a bit\" hostile and \"quite a bit\" nervous at work last week. How does she answer items 6 and 10, and which score do they count toward?","img":"img/mgt102/figure-3-4.png","options":["She writes 4 for each, and both count toward her positive mood score","She writes 3 for each, and both count toward her negative mood score","She writes 4 for each; item 6 counts as negative and item 10 as positive","She writes 4 for each, and both count toward her negative mood score"],"answer":3,"why":"في سلّم الشكل Quite a bit = 4. وفي الـ Scoring العبارات 2, 5, 6, 8, 10, 12 تنجمع للـ negative mood، فـ 6 (Hostile) و 10 (Nervous) الاثنين سلبي.","wrong":[{"i":0,"mis":"c3.mood-figure","note":"الرقم صح، بس الـ positive mood هو العبارات 1, 3, 4, 7, 9, 11، و 6 و 10 مو منها."},{"i":1,"mis":"c3.mood-figure","note":"في سلّم الشكل 3 معناها Moderately، و Quite a bit أعلى منها وهي 4، فقريت السلّم غلط."},{"i":2,"mis":"c3.mood-figure","note":"العبارة 10 هي Nervous وهي من العبارات السلبية (2, 5, 6, 8, 10, 12)، مو إيجابية."}],"tests":["figure 3.4","measure of positive and negative mood at work","negative mood","positive mood"]},{"n":313,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"figure","topic":"figure-3-5-use-of-emotion","stem":"Look at Figure 3.5. Item 11, \"I am a self-motivating person,\" and item 15, \"I would always encourage myself to try my best,\" are summed into which subscale?","img":"img/mgt102/figure-3-5.png","options":["Self-emotions appraisal","Others-emotions appraisal","Use of emotion","Regulation of emotion"],"answer":2,"why":"في الـ Scoring تحت الشكل: Use of emotion = items 3, 7, 11, 15. وكلها عن إنك تحفّز نفسك وتشجعها عشان توصل لأهدافك.","wrong":[{"i":0,"mis":"gen.keyword","note":"كلمة self و myself تسحبك لها، بس Self-emotions appraisal هي العبارات 1, 5, 9, 13 وهي عن فهم مشاعرك، مو تحفيز نفسك."},{"i":1,"mis":"c3.ei-components","note":"Others-emotions appraisal هي العبارات 2, 6, 10, 14 وكلها عن مشاعر الناس الثانيين."},{"i":3,"mis":"c3.ei-components","note":"Regulation of emotion هي العبارات 4, 8, 12, 16 وهي عن التحكم في الغضب والتهدئة، مو التحفيز."}],"tests":["figure 3.5","measure of emotional intelligence","use of emotion","self-emotions appraisal","others-emotions appraisal","regulation of emotion"]},{"n":314,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"list","topic":"ei-interpersonal-roles","stem":"The book says emotional intelligence can help managers perform their interpersonal roles. Which three roles does it name?","options":["Monitor, disseminator, and spokesperson","Figurehead, leader, and liaison","Figurehead, spokesperson, and negotiator","Leader, liaison, and monitor"],"answer":1,"why":"الكتاب يقول الذكاء العاطفي يساعد في الـ interpersonal roles: figurehead, leader, liaison، وهي أدوار Mintzberg الثلاثة اللي فيها تعامل مع الناس من Chapter 1.","wrong":[{"i":0,"mis":"c3.manager-roles","note":"هذي أدوار informational من Chapter 1، مو interpersonal."},{"i":2,"mis":"c3.manager-roles","note":"figurehead و spokesperson هم اللي الكتاب ربطهم بالـ organizational commitment، و negotiator دور decisional."},{"i":3,"mis":"gen.detail","note":"leader و liaison صح، بس monitor دور informational، والثالث الصح هو figurehead."}],"tests":["interpersonal roles","figurehead","leader","liaison","emotional intelligence"]},{"n":315,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"people","topic":"nadella-ei-culture","stem":"According to the book, which leader turned his company's culture of arrogance and fierce rivalry between departments into one of openness, collaboration, and innovation by focusing on self-awareness and empathy?","options":["Bill Gates, cofounder of Microsoft","Travis Bradberry, president of TalentSmart","Satya Nadella, CEO of Microsoft","Ray Kroc, founder of McDonald's"],"answer":2,"why":"Satya Nadella الرئيس التنفيذي لـ Microsoft هو مثال الكتاب على الذكاء العاطفي: غيّر ثقافة الشركة بالتركيز على self-awareness و empathy. وهو يربط الذكاء العاطفي (LO3-4) بالثقافة التنظيمية.","wrong":[{"i":0,"mis":"gen.keyword","note":"كلمة Microsoft تسحبك له، بس Bill Gates مثاله في الكتاب عن قيم المؤسس واللبس غير الرسمي، مو تغيير الثقافة بالتعاطف."},{"i":1,"mis":"gen.neighbor","note":"Travis Bradberry قارن درجات الذكاء العاطفي بين مدراء أمريكان وصينيين، ما غيّر ثقافة شركة."},{"i":3,"mis":"gen.neighbor","note":"Ray Kroc مثال على قيم المؤسس والقصص في McDonald's من قسم الثقافة، مو الذكاء العاطفي."}],"tests":["satya nadella","self-awareness","empathy","emotional intelligence"]},{"n":316,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"tf","topic":"bradberry-finding","stem":"Travis Bradberry of TalentSmart compared managers from two countries. He found that U.S. managers did better than Chinese managers on the parts of emotional intelligence about other people's feelings.","options":["True","False"],"answer":1,"why":"العبارة مقلوبة: Bradberry لقى إن المدراء الصينيين هم اللي سجّلوا أعلى في جوانب الذكاء العاطفي اللي تركز على مشاعر الآخرين. والسبب إن الناس لما يمارسون سلوكيات مبنية على ثقافتهم، يطوّرون نقاط قوة مختلفة في الذكاء العاطفي.","wrong":[{"i":0,"mis":"gen.reversed","note":"الاسم والشركة صح، بس الفخ في مين سجّل أعلى: الصينيين مو الأمريكان."}],"tests":["travis bradberry","talentsmart","emotional intelligence varies by culture"]},{"n":317,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"vocab","topic":"vocab-linger","stem":"In the sentence \"Even after the argument was over, a feeling of sadness lingered in the office for the rest of the day,\" the word lingered most nearly means:","options":["Disappeared at once","Stayed on for some time","Grew much stronger","Spread to many other places"],"answer":1,"why":"linger يعني يبقى ويظل شوي بعد ما المفروض يروح. ونفس الكلمة في الكتاب: بعد ما ينحل سبب الـ emotion، الشعور ممكن linger على شكل mood أخف.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكس المعنى، الجملة تقول الحزن بقى بقية اليوم."},{"i":2,"mis":"gen.vocab","note":"linger ما فيها زيادة قوة، الشعور بس بقى، وفي الكتاب يبقى على شكل mood أخف كمان."},{"i":3,"mis":"gen.vocab","note":"linger عن البقاء في نفس المكان وقت أطول، مو الانتشار لأماكن ثانية."}],"tests":["linger"]},{"n":318,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"vocab","topic":"vocab-assumption","stem":"In the sentence \"The manager made the assumption that the quiet engineer was not interested, but she never asked him,\" the word assumption most nearly means:","options":["A fact that has been proven","A question asked to find out more","Something believed without proof","A final decision made by a group"],"answer":2,"why":"assumption = افتراض، يعني شي تصدقه بدون دليل وبدون ما تتحقق منه. والجملة تقول المديرة ما سألته أبد، يعني بنت رأيها على ظن بس.","wrong":[{"i":0,"mis":"gen.vocab","note":"الافتراض عكس الحقيقة المثبتة، هي ما تحققت من شي."},{"i":1,"mis":"gen.vocab","note":"السؤال هو اللي كان المفروض تسويه (follow-up questions)، بس هي ما سألته."},{"i":3,"mis":"gen.vocab","note":"ما فيه مجموعة ولا قرار رسمي، هي ظنّت لحالها."}],"tests":["assumption"]},{"n":319,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"vocab","topic":"vocab-resign","stem":"What does the word \"resign\" mean?","options":["يوقّع على عقد جديد","ينطرد من وظيفته","يترقّى لوظيفة أعلى","يستقيل من وظيفته"],"answer":3,"why":"resign = يستقيل، يعني يترك شغله بقراره هو. والكتاب يقول موظفين المدير اللي مزاجه إيجابي أقل احتمال إنهم resign ويتركون المنظمة.","wrong":[{"i":0,"mis":"gen.vocab","note":"الكلمة فيها sign (يوقّع) فتلخبطك، بس resign معناها يترك الوظيفة."},{"i":1,"mis":"gen.vocab","note":"الانطراد يكون بقرار المدير (fired)، و resign بقرار الموظف نفسه."},{"i":2,"mis":"gen.vocab","note":"الترقية اسمها promotion، وما لها علاقة بترك الوظيفة."}],"tests":["resign"]},{"n":320,"lo":"LO3-3","sec":"MGT102-CH3-S3","type":"vocab","topic":"vocab-intense","stem":"What does the word \"intense\" mean?","options":["خفيف وهادئ","شديد وقوي","مقصود ومتعمّد","طويل ومستمر"],"answer":1,"why":"intense = شديد وقوي. وهي الكلمة المفتاح في تعريف الـ emotions: Intense, relatively short-lived feelings.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكس المعنى، والخفيف أقرب لوصف الـ mood لأنه أقل شدة من الـ emotion."},{"i":2,"mis":"gen.vocab","note":"هذي معنى intentional، شكلها قريب من intense بس المعنى مختلف."},{"i":3,"mis":"gen.vocab","note":"الطويل المستمر عكس الـ emotions اللي هي short-lived، وما هو معنى intense."}],"tests":["intense","emotions"]},{"n":401,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"term","topic":"org-culture-definition","stem":"According to the chapter, organizational culture is the shared set of which elements that influence how members of an organization relate to one another and work together to achieve organizational goals?","options":["Beliefs, expectations, values, norms, and work routines","Rules, policies, job titles, reporting lines, and procedures","Personality traits, moods, emotions, attitudes, and skills","Beliefs, values, norms, written rules, and job titles"],"answer":0,"why":"التعريف فيه خمس أجزاء بالضبط: beliefs · expectations · values · norms · work routines، وكلها أشياء مشتركة بين الأعضاء. أي خيار يدخّل قواعد مكتوبة أو هيكل أو سمات شخصية فهو غلط.","wrong":[{"i":1,"mis":"c3.culture-def","note":"القواعد والمسميات وخطوط الرفع جزء من الهيكل الرسمي، والتعريف ما فيه أي شي رسمي مكتوب."},{"i":2,"mis":"gen.neighbor","note":"هذي خصائص الفرد من أول الفصل، والثقافة شي مشترك يخلي أعضاء المنظمة يتصرفون بطرق متشابهة."},{"i":3,"mis":"c3.culture-def","note":"فيه beliefs وvalues وnorms صح، بس حط written rules وjob titles مكان expectations وwork routines."}],"tests":["organizational culture"]},{"n":402,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"term","topic":"strong-culture-personality-dimensions","stem":"The chapter says that the stronger an organization's culture is, the more it can be thought of as the organization's 'personality.' What makes an organization's culture strong?","options":["Nearly all members are deeply committed to the same values, beliefs, and routines","Members relate informally, make decisions bottom-up, and treat their work playfully","Members relate formally, make decisions top-down, and treat their work seriously","Members hold only a loose commitment to a shared set of values, beliefs, and routines"],"answer":0,"why":"الثقافة القوية = تقريباً كل الأعضاء ملتزمين بقوة بنفس القيم والمعتقدات والروتين ويستخدمونها عشان يوصلون لأهدافهم، وكل ما زادت قوتها صارت زي «شخصية» المنظمة. أما رسمي أو غير رسمي، من فوق أو من تحت، جاد أو مرح، فهذي أبعاد (dimensions) تختلف فيها الثقافات القوية عن بعض، زي IDEO المرحة قدام Citibank و ExxonMobil الرسمية.","wrong":[{"i":1,"mis":"gen.neighbor","note":"هذا وصف ثقافة IDEO، بس غير رسمي ومن تحت ومرح أبعاد تختلف فيها الثقافات، مو اللي يخلي الثقافة قوية."},{"i":2,"mis":"gen.keyword","note":"كلمة strong توحي بالرسمية والصرامة، بس الرسمية بُعد تختلف فيه الثقافات القوية، مو مقياس قوتها."},{"i":3,"mis":"gen.reversed","note":"قلبتها: الالتزام الضعيف بنظام قيم وروتين مشترك هو تعريف الثقافة الضعيفة."}],"tests":["strong organizational culture","weak organizational culture","culture as the organization's personality","dimensions on which strong cultures differ (formal/informal, top-down/bottom-up, flexible/unyielding, creative/predictable, serious/serendipitous)"]},{"n":403,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"term","topic":"organizational-socialization","stem":"The process through which new members learn an organization's values and norms and pick up the work behaviors they need to do their jobs effectively is called:","options":["The attraction–selection–attrition process","A rite of enhancement","Organizational socialization","Organizational language"],"answer":2,"why":"الكلمة المفتاح: الجداد (newcomers) يتعلمون values and norms ويكتسبون work behaviors = organizational socialization، والنتيجة إنهم يستدخلون القيم ويتصرفون وفقها.","wrong":[{"i":0,"mis":"c3.asa-framework","note":"ASA يشرح مين ينجذب ومين ينختار ومين يطلع حسب تشابه الشخصية، مو كيف الجديد يتعلم القيم."},{"i":1,"mis":"c3.rites-swap","note":"طقس التعزيز فعالية رسمية تكرّم مساهمات الموظفين قدام الكل، مو عملية تعليم للجداد."},{"i":3,"mis":"c3.transmit-factors","note":"اللغة التنظيمية من عوامل نقل الثقافة، بس عملية تعليم الجداد لها اسم خاص: socialization."}],"tests":["organizational socialization"]},{"n":404,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"term","topic":"ceremonies-and-rites","stem":"Which term does the chapter use for formal events that mark incidents that matter to the whole organization and to particular employees?","options":["Norms","Organizational ceremonies and rites","Stories and language","Organizational socialization"],"answer":1,"why":"الكلمة المفتاح formal events: المراسم والطقوس فعاليات رسمية تحتفي بأحداث مهمة للمنظمة كلها ولموظفين معيّنين، وأشهر أنواعها passage وintegration وenhancement.","wrong":[{"i":0,"mis":"c3.norms-formal","note":"الأعراف عكسها: قواعد غير مكتوبة وغير رسمية، أما المراسم فعاليات رسمية."},{"i":2,"mis":"c3.transmit-factors","note":"القصص واللغة عامل نقل ثاني، حكايات عن أبطال وأشرار وكلمات خاصة، مو فعاليات رسمية."},{"i":3,"mis":"gen.neighbor","note":"socialization عملية تعليم الجداد قيم المنظمة، مو فعاليات رسمية تحتفي بأحداث مهمة."}],"tests":["organizational ceremonies and rites","norms"]},{"n":405,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"shared-values-and-norms","stem":"The chapter explains the role of shared values and norms in organizational culture, using IDEO as an example. Which statement is correct?","options":["Terminal values guide how members reach their goals; norms are unwritten rules, like not criticizing others' ideas.","Terminal values show what the organization aims for; norms are unwritten rules, like not criticizing others' ideas.","Terminal values show what the organization aims for; norms are written policies, like a rule to build prototypes.","Terminal values guide how members reach their goals; norms are lasting personality traits, like openness to experience."],"answer":1,"why":"terminal values تبيّن وش تبي المنظمة وموظفينها يحققون، والـinstrumental هي اللي ترشد كيف يوصلون. والـnorms جانب أساسي من الثقافة: قواعد غير مكتوبة وغير رسمية تحدد التصرف المناسب، وأمثلتها في IDEO: ما تنتقد أفكار غيرك، تطلع بأكثر من فكرة قبل ما تختار، وتسوي prototypes للمنتجات.","wrong":[{"i":0,"mis":"c3.terminal-vs-instrumental","note":"نص الأعراف صح، بس قلبت القيم: اللي ترشد كيف يوصلون للأهداف هي instrumental، والـterminal هي الغاية نفسها."},{"i":2,"mis":"c3.norms-formal","note":"الـprototypes فعلاً من أعراف IDEO، بس الأعراف غير مكتوبة وغير رسمية، مو سياسات مكتوبة."},{"i":3,"mis":"gen.neighbor","note":"غلط في الاثنين: السمات زي openness to experience خصائص فرد من أول الفصل مو أعراف مشتركة، والـterminal هي الغاية مو الطريقة."}],"tests":["shared terminal values","shared instrumental values","norms","ideo's norms (not criticizing others' ideas, multiple ideas before settling on one, prototypes)"]},{"n":406,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"asa-limits","stem":"Which statement about the attraction–selection–attrition (ASA) framework is correct according to the chapter?","options":["ASA processes are most evident in large companies, where hiring is more formal and selective.","Since similar people get along well, more similarity among members makes the organization more effective.","Dissimilar people may be hired but tend to leave, and too much similarity can hurt effectiveness.","It explains how an organization's culture gradually reshapes the personalities of the people who stay."],"answer":2,"why":"الكتاب يقول المختلفين في الشخصية ممكن ينوظّفون بس الأرجح يطلعون مع الوقت (attrition)، وينبّه إن التشابه الزايد يضرّ الفعالية لأن المتشابهين يشوفون الأمور بنفس الطريقة ويقاومون التغيير.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبتها: الكتاب يقول ASA أوضح في الشركات الصغيرة زي IDEO، وممكن تشتغل كمان في الكبيرة."},{"i":1,"mis":"gen.partial","note":"أخذت نص الفكرة: صح إن المتشابهين يتفاهمون، بس الكتاب يقول التشابه الزايد يضرّ الفعالية لأنهم يقاومون التغيير."},{"i":3,"mis":"c3.asa-framework","note":"قلبت الاتجاه: ASA يشرح كيف الشخصية تأثّر على الثقافة، مو كيف الثقافة تغيّر الشخصيات."}],"tests":["attraction–selection–attrition (asa) framework","attrition","asa is most evident in small firms","too much similarity impairs effectiveness"]},{"n":407,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"dysfunctional-culture","stem":"According to the chapter, which statement about organizational culture and managerial action is correct?","options":["Conservative, cautious cultures are dysfunctional, because their formal reviews slow decision making.","Founders and managers create culture, but once formed it shapes only lower-level employees' behavior.","A strong culture always leads managers to take actions that benefit the organization's performance.","Some cultures become dysfunctional, encouraging managerial actions that harm the organization."],"answer":3,"why":"الكتاب يقول الثقافة مو دايماً تفيد: بعض الثقافات تصير dysfunctional، تشجّع تصرفات إدارية تضرّ المنظمة وتمنع التصرفات اللي ممكن تحسّن الأداء، زي Boeing و Wells Fargo. والسبب إن الثقافة تشكّل تصرفات المدراء، وتصرفاتهم تأثّر على أداء المنظمة، فالثلاثة كلها مربوطة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المحافظة مو يعني مختلّة: الكتاب يقول الحذر مناسب في المحطات النووية والبنوك، والمختلّة هي اللي تشجّع تصرفات تضرّ المنظمة."},{"i":1,"mis":"c3.culture-two-way","note":"الكتاب صريح إن نفس الثقافة تشكّل وتتحكم في سلوك كل الموظفين، والمدراء نفسهم منهم."},{"i":2,"mis":"gen.absolute","note":"كلمة always هي الفخ: الكتاب يقول مو دايماً الثقافة تجيب تصرفات مفيدة، وبعضها يصير dysfunctional."}],"tests":["dysfunctional culture","culture and managerial action","managers both create and are influenced by culture","organizational performance","conservative culture"]},{"n":408,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"scenario","topic":"planning-conservative-culture","stem":"At an insurance company in Riyadh, top managers value caution: staff must consult their superiors before any change to the status quo, and detailed records are kept to make sure procedures are followed. Based on the chapter, how are these top managers most likely to handle planning?","options":["Invite lower-level managers into the planning process and keep plans flexible","Use formal top-down planning, with lower-level ideas sent to a formal review","Lead by example and stay supportive of employees whether they succeed or fail","Accept failure so creativity can thrive, and focus on long-term performance"],"answer":1,"why":"الموقف ثقافة محافظة: حذر، رجوع للرؤساء قبل أي تغيير، وسجلات تفصيلية. والمدراء العليا في الثقافة المحافظة يركّزون على formal top-down planning، واقتراحات المدراء الأدنى تمر بمراجعة رسمية (formal review) ممكن تبطّئ القرار، زي IBM زمان.","wrong":[{"i":0,"mis":"c3.innovative-vs-conservative","note":"إشراك المدراء الأدنى والتخطيط المرن = تخطيط الثقافة المبتكرة، عكس الشركة الحذرة اللي في الموقف."},{"i":2,"mis":"c3.innovative-vs-conservative","note":"القيادة بالقدوة ودعم الموظف لو فشل = قيادة الثقافة المبتكرة، والسؤال عن تخطيط شركة محافظة."},{"i":3,"mis":"c3.innovative-vs-conservative","note":"تقبّل الفشل والتركيز على المدى الطويل = رقابة الثقافة المبتكرة، مو تخطيط ثقافة محافظة."}],"tests":["planning in innovative vs conservative cultures","formal top-down planning","formal review process","conservative culture","innovative culture","leading in innovative cultures","controlling in innovative cultures"]},{"n":409,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"scenario","topic":"stories-and-language","stem":"At a hospital in Riyadh, staff often tell each other about a nurse who, years ago, stayed a whole night after her shift to care for a patient who had no family. Nobody is sure the story is completely true, but it is retold again and again, and staff take from it that patient care comes before personal comfort. Which factor that maintains and transmits organizational culture does this mainly show?","options":["Values of the founder","Ceremonies and rites","The attraction–selection–attrition process","Stories and language"],"answer":3,"why":"حكاية عن بطلة في المنظمة تنعاد وتنحكى وتبيّن وش السلوك اللي تقدّره المنظمة = stories and language. والكتاب يقول القصص تشتغل سواء كانت حقيقية أو خيالية (fact or fiction).","wrong":[{"i":0,"mis":"c3.transmit-factors","note":"الممرضة موظفة مو مؤسِّسة المستشفى، فهذا مو values of the founder."},{"i":1,"mis":"c3.transmit-factors","note":"المراسم والطقوس فعاليات رسمية، وهنا حكاية يتناقلها الموظفين بدون أي حفل."},{"i":2,"mis":"c3.asa-framework","note":"ASA عن جذب واختيار وتسرّب ناس شخصياتهم متشابهة، مو عن حكايات تنقل القيم."}],"tests":["stories","heroes and villains","stories can be fact or fiction"]},{"n":410,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"scenario","topic":"managers-values-moods-shape-culture","stem":"A new manager at a hotel in Madinah cares a lot about being helpful and forgiving. He never punishes honest mistakes, and he is almost always in a cheerful, enthusiastic mood. Over two years, with the same staff and no new hires, employees start helping each other, accepting each other's mistakes, and showing more enthusiasm. Which explanation fits the chapter best?","options":["Managers' influence on culture, because his own values and moods spread to the staff","The ASA framework, because the hotel kept only staff whose personalities matched his","Organizational socialization, because newcomers learned the hotel's values in training","A rite of enhancement, because he publicly rewarded staff contributions with awards"],"answer":0,"why":"الكتاب يقول قيم المدير (terminal و instrumental) تشارك في تشكيل الثقافة: اللي يقدّر الحرية والمساواة يركّز على autonomy و empowerment، واللي يقدّر إنه helpful و forgiving يتقبّل الأخطاء ويركّز إن الموظفين يساعدون بعض. ومزاجه الإيجابي معدي (contagious) فينتقل للي حوله، والموظفين نفسهم ما تغيّروا، فهو مو ASA ولا socialization.","wrong":[{"i":1,"mis":"c3.asa-framework","note":"ASA يصير لما المختلفين يطلعون ويبقى المتشابهين، والموقف قال الموظفين ما تغيّروا أبد."},{"i":2,"mis":"gen.neighbor","note":"socialization تخص الموظفين الجداد، والموقف كله عن نفس الفريق القديم بدون توظيف."},{"i":3,"mis":"c3.rites-swap","note":"ما فيه جوائز ولا تكريم علني في الموقف، اللي انتقل هو قيم المدير ومزاجه لفريقه."}],"tests":["managers' values shape culture","managers' terminal and instrumental values (helpful and forgiving → tolerance of mistakes; freedom and equality → autonomy and empowerment)","managers' moods and emotions shape culture","moods and emotions are contagious"]},{"n":411,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"scenario","topic":"organizing-innovative-culture","stem":"The founders of an app-development company in Riyadh value risk taking, experimentation, and autonomy, and they see failure as part of learning. Based on the chapter, how are managers in this kind of culture most likely to organize the company?","options":["Set up a flat, organic structure with decentralized authority, such as product teams","Set up a well-defined hierarchy of authority with clear lines of who reports to whom","Set specific, difficult goals and frequently monitor progress toward those goals","Use management by objectives and closely monitor every move that employees make"],"answer":0,"why":"الموقف ثقافة مبتكرة: مخاطرة، تجريب، استقلالية، وتقبّل للفشل. والمدراء في الثقافة المبتكرة ينظّمون بهيكل organic: مسطّح، مستويات قليلة، وسلطة لامركزية عشان الموظفين يشتغلون مع بعض، والكتاب يقول product team structure ممكن يناسبها.","wrong":[{"i":1,"mis":"c3.innovative-vs-conservative","note":"الهرم الواضح وخطوط الرفع المحددة = تنظيم الثقافة المحافظة، عكس الشركة اللي في الموقف."},{"i":2,"mis":"c3.innovative-vs-conservative","note":"أهداف محددة وصعبة ومتابعة متكررة = رقابة الثقافة المحافظة، والمبتكرة تهتم بالأداء طويل الأمد وتتقبّل الفشل."},{"i":3,"mis":"c3.innovative-vs-conservative","note":"management by objectives ومراقبة كل حركة = قيادة الثقافة المحافظة، والمبتكرة تقود بالقدوة."}],"tests":["organizing in innovative vs conservative cultures","organic structure","product team structure","hierarchy of authority and reporting relationships","management by objectives","controlling in conservative cultures","innovative culture","conservative culture","culture and the four management functions"]},{"n":412,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"figure","topic":"transmit-factors-figure","stem":"Look at Figure 3.6. Which group lists only factors that the figure shows as maintaining and transmitting organizational culture?","img":"img/mgt102/figure-3-6.png","options":["Values of the founder, attraction–selection–attrition, ceremonies and rites","Socialization, organizational structure, stories and language","Values of the founder, socialization, stories and language","Ceremonies and rites, shared norms, values of the founder"],"answer":2,"why":"في Figure 3.6 أربع دوائر بس تأشّر على Organizational culture: Values of the founder · Socialization · Ceremonies and rites · Stories and language. الخيار الصح فيه ثلاثة منها بدون دخيل.","wrong":[{"i":0,"mis":"c3.asa-framework","note":"ASA يشرح كيف الشخصية تكوّن الثقافة، بس مو وحدة من الدوائر الأربع في الشكل."},{"i":1,"mis":"c3.transmit-factors","note":"organizational structure مو موجود في الشكل، وهو من الفصل الأول مو من عوامل نقل الثقافة."},{"i":3,"mis":"c3.transmit-factors","note":"الأعراف جزء من تعريف الثقافة نفسها، مو دائرة من الدوائر اللي تحافظ عليها وتنقلها."}],"tests":["figure 3.6","factors that maintain and transmit organizational culture","values of the founder","organizational socialization","ceremonies and rites","stories and language"]},{"n":413,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"figure","topic":"rites-table","stem":"Look at Table 3.1. Which type of rite has the purpose \"learn and internalize norms and values,\" and what example does the table give for it?","img":"img/mgt102/table-3-1.png","options":["Rite of integration; induction and basic training","Rite of passage; presentation of annual awards","Rite of enhancement; office holiday party","Rite of passage; induction and basic training"],"answer":3,"why":"اقرأ الصف الأول في Table 3.1: Rite of passage، مثاله Induction and basic training، وهدفه Learn and internalize norms and values.","wrong":[{"i":0,"mis":"c3.rites-swap","note":"المثال صح بس النوع غلط: integration مثاله office holiday party وهدفه build common norms and values."},{"i":1,"mis":"c3.rites-swap","note":"النوع صح بس المثال من صف enhancement، والجوائز السنوية هدفها motivate commitment."},{"i":2,"mis":"c3.rites-swap","note":"غلط في الاثنين: office holiday party مثال integration، ومثال enhancement هو presentation of annual awards."}],"tests":["table 3.1","rites of passage","rites of integration","rites of enhancement"]},{"n":414,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"list","topic":"rites-matching","stem":"A company holds three events: (1) a program that prepares long-serving staff for retirement, (2) its annual meeting, which celebrates the company's success with managers, employees, and shareholders, and (3) a social media post that praises one employee's contribution. According to the chapter, which list matches each event to its type of rite?","options":["(1) passage; (2) enhancement; (3) integration","(1) passage; (2) integration; (3) enhancement","(1) enhancement; (2) integration; (3) passage","(1) integration; (2) enhancement; (3) passage"],"answer":1,"why":"passage = كيف الموظف يدخل المنظمة ويتقدّم فيها ويطلع منها، ومنها تجهيز الناس للترقية أو التقاعد. integration = يبني روابط مشتركة، والكتاب يقول الاجتماع السنوي ممكن يكون ritual of integration زي اجتماع Walmart. enhancement = تكريم علني لمساهمات الموظفين، زي awards dinners والتقدير في press releases و social media posts.","wrong":[{"i":0,"mis":"c3.rites-swap","note":"التقاعد صح، بس قلبت 2 و3: الاجتماع السنوي يحتفي بنجاح الشركة مع الكل فهو integration، ومدح موظف واحد علناً على مساهمته enhancement."},{"i":2,"mis":"c3.rites-swap","note":"الاجتماع السنوي صح، بس التجهيز للتقاعد يخص خروج الموظف فهو passage، ومدح موظف على مساهمته enhancement مو passage."},{"i":3,"mis":"c3.rites-swap","note":"غلطت في الثلاثة: التقاعد passage لأنه خروج من المنظمة، والاجتماع السنوي integration، والمدح العلني لموظف enhancement."}],"tests":["rites of passage","rites of integration","rites of enhancement","preparing people for promotion or retirement is a rite of passage","annual meeting as a ritual of integration","recognition in press releases and social media posts"]},{"n":415,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"people","topic":"asa-schneider-founders","stem":"Which pairing of a person and what the chapter says about him is correct?","options":["David Kelley: developed the attraction–selection–attrition (ASA) framework","Bill Gates: insisted on QSC&V — quality, service, cleanliness, and value for money","Benjamin Schneider: developed the attraction–selection–attrition (ASA) framework","Ray Kroc: founded IDEO, whose culture embodies his playful, freewheeling approach"],"answer":2,"why":"صاحب نموذج ASA هو الباحث Benjamin Schneider. أما David Kelley فهو مؤسس IDEO والكتاب يستخدمه مثال على ASA، وQSC&V حق Ray Kroc في McDonald's.","wrong":[{"i":0,"mis":"gen.theorist","note":"Kelley مؤسس IDEO والكتاب جابه مثال على ASA، بس اللي طوّر النموذج Schneider."},{"i":1,"mis":"gen.detail","note":"QSC&V قيم Ray Kroc مؤسس McDonald's، أما Bill Gates فمثاله اللبس غير الرسمي وفعاليات Microsoft."},{"i":3,"mis":"gen.detail","note":"Ray Kroc مؤسس McDonald's وصاحب QSC&V، واللي أسّس IDEO هو David Kelley."}],"tests":["benjamin schneider","attraction–selection–attrition (asa) framework","david kelley","ray kroc","qsc&v","values of the founder"]},{"n":416,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"tf","topic":"organizational-language-scope","stem":"According to the chapter, organizational language includes not only spoken language but also how people dress, the offices they occupy, and the cars they drive.","options":["True","False"],"answer":0,"why":"صح. الكتاب يقول organizational language أوسع من الكلام: تشمل اللبس والمكاتب والسيارات ودرجة الرسمية لما يخاطبون بعض. مثاله لبس IDEO الكاجوال اللي يعكس ثقافتها الريادية.","wrong":[{"i":1,"mis":"c3.transmit-factors","note":"تحسب اللغة كلام بس، فتودّي اللبس والمكاتب لـ ceremonies and rites، والكتاب حاطها داخل organizational language."}],"tests":["organizational language","slang / jargon","ceremonies and rites"]},{"n":417,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"vocab","topic":"vocab-permeate","stem":"In the sentence 'The smell of fresh bread permeated the whole bakery, reaching even the small office at the back,' the word permeated most nearly means:","options":["Spread through every part of","Stayed in one corner of","Was quickly removed from","Slowly disappeared from"],"answer":0,"why":"permeate يعني ينتشر ويتغلغل في كل مكان. والدليل في الجملة: الريحة وصلت حتى للمكتب الصغير اللي ورا.","wrong":[{"i":1,"mis":"gen.vocab","note":"عكس المعنى: لو بقت في زاوية وحدة ما كانت وصلت للمكتب اللي ورا."},{"i":2,"mis":"gen.vocab","note":"الجملة تقول الريحة وصلت لكل مكان، مو إن أحد شالها."},{"i":3,"mis":"gen.vocab","note":"permeate معناها تنتشر أكثر، مو تختفي شوي شوي."}],"tests":["permeate"]},{"n":418,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"vocab","topic":"vocab-unyielding","stem":"In the sentence 'The coach was unyielding: no matter how many times the players asked, he refused to cancel the morning training,' the word unyielding most nearly means:","options":["Kind and understanding","Confused and unsure","Firm and unwilling to change","Tired and impatient"],"answer":2,"why":"unyielding يعني متصلّب وما يلين ولا يغيّر رايه. والدليل: مهما طلبوا منه، رفض يلغي التمرين.","wrong":[{"i":0,"mis":"gen.vocab","note":"اللطيف المتفهّم كان بيوافق، وهو رفض كل مرة."},{"i":1,"mis":"gen.vocab","note":"ما فيه أي حيرة في الجملة، كان واضح ورافض."},{"i":3,"mis":"gen.vocab","note":"ممكن يكون تعبان، بس الكلمة تصف إنه ما يتنازل ولا يتغيّر."}],"tests":["unyielding"]},{"n":419,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"vocab","topic":"vocab-catastrophic","stem":"What does the word 'catastrophic' mean?","options":["مؤقت","كارثي","متوقّع","بسيط"],"answer":1,"why":"catastrophic يعني كارثي، ضرره ضخم جداً. زي مثال الكتاب: في المحطة النووية عواقب الخطأ كارثية، فالإشراف العالي ضروري.","wrong":[{"i":0,"mis":"gen.vocab","note":"مؤقت يعني temporary، والكلمة عن حجم الضرر مو مدته."},{"i":2,"mis":"gen.vocab","note":"متوقّع يعني expected، والكلمة عن ضرر ضخم مو عن التوقع."},{"i":3,"mis":"gen.vocab","note":"بسيط عكسها تماماً، catastrophic أكبر ضرر ممكن."}],"tests":["catastrophic"]},{"n":420,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"vocab","topic":"vocab-internalize","stem":"What does the word 'internalize' mean?","options":["يحفظه عن ظهر قلب","ينقله لغيره","يطبّقه بس لأن المدير أمره","يصير جزء من قناعته"],"answer":3,"why":"internalize يعني القيمة تصير جزء منك وتسويها عن قناعة. الكتاب يقول بعد socialization الأعضاء يستدخلون قيم المنظمة ويتصرفون وفقها، مو بس لأنهم مجبورين.","wrong":[{"i":0,"mis":"gen.vocab","note":"الحفظ يعني memorize، تقدر تحفظ قيمة وأنت مو مقتنع فيها، أما internalize فتصير جزء منك."},{"i":1,"mis":"gen.vocab","note":"هذي transmit، والـinternalize إنك أنت تتبنّى القيمة من داخلك."},{"i":2,"mis":"gen.vocab","note":"هذا عكس الفكرة: اللي يستدخل القيمة يتصرف وفقها لأنه مقتنع إنها الصح، مو بس لأنه مجبور."}],"tests":["internalize"]},{"n":901,"lo":"LO3-1","sec":"CASE","type":"case","topic":"locus-of-control","stem":"Which personality trait does Faisal show in the way he reacts to the missed delivery target?","caseId":"C3-A","options":["An external locus of control","An internal locus of control","High negative affectivity","A high need for affiliation"],"answer":1,"why":"فيصل ما رمى اللوم على زحمة الميناء ولا الحظ، قال نتايج الفرع تعتمد على قراراته هو، وقام يعدّل المسارات بنفسه. هذا internal locus of control: تحط مسؤولية مصيرك في نفسك مو في قوى برّا.","wrong":[{"i":0,"mis":"c3.locus-reversed","note":"يمكن تختاره لأنك شفت 'port traffic and bad luck' في القصة، بس هذا كلام المشرفين وفيصل رفضه، والـ external يرمي المسؤولية على قوى برّا وما يتدخّل يحل المشكلة."},{"i":2,"mis":"c3.trait-vs-mood","note":"يمكن تختاره لأنه غضب وصار كئيب بعد مكالمة العميل، بس هذي مشاعر مؤقتة طلعت من موقف وخفّت، والـ negative affectivity سمة شخصية ثابتة يعني ميل دايم للضيق وانتقاد النفس والغير، وهو أصلاً تكلم مع الفريق بهدوء."},{"i":3,"mis":"gen.neighbor","note":"need for affiliation يعني تبي تكون محبوب وتبي الناس متفاهمين، وفيصل ما سوّى شي عشان يرضّي أحد، هو بس حط مسؤولية النتيجة على قراراته."}],"tests":["locus of control","internal locus of control","external locus of control"]},{"n":902,"lo":"LO3-2","sec":"CASE","type":"case","topic":"commitment-vs-satisfaction","stem":"What Faisal tells his friends about Marsa best reflects which of the following?","caseId":"C3-A","options":["Job satisfaction","A terminal value","Organizational commitment","Organizational citizenship behavior"],"answer":2,"why":"يؤمن باللي تسويه الشركة، فخور باللي تمثّله، ومخلص لها: هذي بالضبط أوصاف organizational commitment، يعني مشاعره ومعتقداته عن المنظمة ككل. والدليل إنها مو job satisfaction إنه قال وظيفته الحالية متعبة وراتبه عادي.","wrong":[{"i":0,"mis":"c3.satisfaction-vs-commitment","note":"التعريفين شبه بعض، بس job satisfaction عن الوظيفة الحالية، وفيصل أصلاً قال وظيفته متعبة وراتبه عادي، وكلامه لأصحابه عن الشركة ككل."},{"i":1,"mis":"c3.values-vs-attitudes","note":"يمكن كلمة 'believes' خلتك تفكر في القيم، بس terminal value هدف تبيه طول عمرك، وهنا هو يوصف مشاعره ومعتقداته عن الشركة، وهذا attitude."},{"i":3,"mis":"gen.neighbor","note":"OCB سلوك فوق الواجب زي إنك تساعد زميل بدون ما أحد يطلب منك، وفيصل هنا ما سوّى سلوك زيادة، بس يتكلم عن إحساسه تجاه الشركة."}],"tests":["organizational commitment","job satisfaction","attitude"]},{"n":903,"lo":"LO3-3","sec":"CASE","type":"case","topic":"emotion-vs-mood","stem":"In the book's terms, the anger Faisal felt right after the call and the gloomy feeling that stayed with him for the rest of the day are best described as:","caseId":"C3-A","options":["A mood, then an emotion","Negative affectivity, then a mood","An emotion, then a mood","An emotion, then an attitude"],"answer":2,"why":"الغضب كان قوي وقصير ومرتبط مباشرة بالمكالمة، وهذا emotion. وبعد ما قرّر كيف يتصرف خفّ، وبقى إحساس أخف طول اليوم حتى وهو مو مفكّر في المكالمة، وهذا mood. نفس مثال الكتاب بالضبط.","wrong":[{"i":0,"mis":"c3.mood-vs-emotion","note":"قلبت الترتيب: الشي القوي القصير المرتبط بسببه هو emotion، والأخف اللي يطوّل بعده هو mood."},{"i":1,"mis":"c3.trait-vs-mood","note":"negative affectivity سمة شخصية ثابتة، مو إحساس يطلع بعد مكالمة وحدة ويخف خلال ساعة."},{"i":3,"mis":"c3.values-vs-attitudes","note":"attitude مجموعة مشاعر ومعتقدات عن شي معيّن زي الوظيفة أو المنظمة، أما الإحساس الكئيب الأخف اللي بقى طول اليوم فهو mood."}],"tests":["emotions","mood"]},{"n":904,"lo":"LO3-5","sec":"CASE","type":"case","topic":"asa-framework","stem":"Looking at how Wasl's culture formed, the careful, rule-loving designers who resigned within a year best illustrate which process?","caseId":"C3-B","options":["Attraction","Selection","Socialization","Attrition"],"answer":3,"why":"Attrition يعني التسرّب: الموظفين اللي شخصياتهم مختلفة عن المؤسِّس ممكن ينوظّفون، بس الأرجح يطلعون مع الوقت. والمصممين الحذرين انضموا فعلاً بس طلعوا خلال سنة لأنهم ما حسّوا إنهم مناسبين.","wrong":[{"i":0,"mis":"c3.asa-framework","note":"Attraction هي البداية: المرشحين اللي يشبهون نورة انجذبوا للاستوديو وهي انجذبت لهم، مو خروج الناس المختلفين عنها بعد ما توظّفوا."},{"i":1,"mis":"c3.asa-framework","note":"Selection هي إنها اختارت ووظّفت المشابهين لها، أما اللي استقالوا بعدين فهذي مرحلة التسرّب."},{"i":2,"mis":"gen.neighbor","note":"Socialization عملية يتعلم فيها الموظفين الجدد قيم المنظمة وأعرافها ويمشون عليها، بس هالمصممين ما تأقلموا مع ثقافة وصل، طلعوا منها."}],"tests":["attraction–selection–attrition framework","attrition","organizational socialization"]},{"n":905,"lo":"LO3-5","sec":"CASE","type":"case","topic":"organizational-rites","stem":"Nora's December dinner is best classified as which of the following?","caseId":"C3-B","options":["A rite of integration","A rite of enhancement","A rite of passage","An organizational norm"],"answer":1,"why":"العشاء هذا يكرّم موظفين محدّدين علناً على مساهمتهم وينشر صورهم في السوشال ميديا، وهذا rite of enhancement زي Presentation of annual awards في Table 3.1، وغرضه يحفّز الالتزام بقيم المنظمة وأعرافها.","wrong":[{"i":0,"mis":"c3.rites-swap","note":"غداء الخميس هو اللي rite of integration لأنه يبني روابط مشتركة بين الكل، بس عشاء ديسمبر يكرّم ناس معيّنين على إنجازهم."},{"i":2,"mis":"c3.rites-swap","note":"rite of passage يحدّد كيف الناس يدخلون المنظمة ويتقدّمون فيها ويطلعون منها، زي التدريب الأساسي، والعشاء هنا تكريم مو دخول."},{"i":3,"mis":"gen.neighbor","note":"يمكن تحسبه عُرف لأنه شي يتكرر كل سنة، بس الـ norms توقّعات غير مكتوبة عن التصرف الصح، أما العشاء فحفل علني مخطّط له يكرّم ناس، يعني طقس مو عُرف."}],"tests":["ceremonies and rites","rites of enhancement","rites of integration","rites of passage"]},{"n":906,"lo":"LO3-4","sec":"CASE","type":"case","topic":"ei-dimensions","stem":"When Nora noticed Majed's silence and correctly sensed that he was worried, which dimension of emotional intelligence was she showing?","caseId":"C3-B","options":["Self-emotions appraisal","Regulation of emotion","Others-emotions appraisal","Use of emotion"],"answer":2,"why":"إنها قرأت من سكوت ماجد إنه قلقان يعني فهمت مشاعر غيرها، وهذا others-emotions appraisal، البُعد اللي يقيس قراءة مشاعر الناس الثانيين في Figure 3.5.","wrong":[{"i":0,"mis":"c3.ei-components","note":"self-emotions appraisal هو لما نورة فهمت سبب عصبيتها هي (خوفها من الموعد)، مو لما قرأت مشاعر ماجد."},{"i":1,"mis":"c3.ei-components","note":"regulation of emotion هو لما طلعت تمشي عشان تهدّي نفسها، يعني تتحكم في مشاعرها هي، مو تفهم مشاعر غيرها."},{"i":3,"mis":"c3.ei-components","note":"use of emotion يعني تستخدم مشاعرك عشان تحفّز نفسك وتحط أهداف، وما له علاقة بقراءة إحساس ماجد."}],"tests":["emotional intelligence","others-emotions appraisal"]},{"n":951,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"list","topic":"culture-definition-elements","stem":"The book defines organizational culture as a shared set of five elements that influence how members relate to one another and work together. Which of the following is NOT one of those five elements?","options":["expectations","work routines","attitudes","norms"],"answer":2,"why":"تعريف الكتاب لـ organizational culture خمسة أشياء بالضبط: beliefs, expectations, values, norms, work routines. الـ attitudes موجودة في الفصل بس في جزء المدير كشخص (job satisfaction و commitment)، مو في تعريف الثقافة.","wrong":[{"i":0,"mis":"c3.culture-def","note":"expectations جزء من التعريف فعلاً، يمكن نسيتها لأنها أقل كلمة تتكرر، بس هي وحدة من الخمسة."},{"i":1,"mis":"c3.culture-def","note":"work routines آخر عنصر في التعريف، والكتاب يمثّل لها بروتين فرق البحث في تطوير المنتجات، فهي داخلة."},{"i":3,"mis":"c3.culture-def","note":"norms من أهم عناصر الثقافة والكتاب يرجع لها كثير مع values، فهي من الخمسة."}],"tests":["organizational culture","beliefs","expectations","values","norms","work routines"]},{"n":952,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"rokeach-instrumental-examples","stem":"Milton Rokeach listed 18 terminal and 18 instrumental values. Which group contains ONLY instrumental values that the book says are important for managers?","options":["sense of accomplishment, equality, self-esteem","ambitious, open-minded, competent","ambitious, equality, responsible","self-esteem, competent, self-disciplined"],"answer":1,"why":"instrumental value = طريقة تصرّف (mode of conduct)، عشان كذا تجي كصفات: ambitious, open-minded, competent, responsible, self-disciplined. أما terminal فهي أهداف العمر: sense of accomplishment, equality, self-esteem. المفتاح: الصفة اللي توصف تصرفك = وسيلة، الشي اللي توصل له = غاية.","wrong":[{"i":0,"mis":"c3.terminal-vs-instrumental","note":"هذي الثلاثة كلها terminal values (أهداف يبي يحققها)، يعني قلبت النوعين."},{"i":2,"mis":"c3.terminal-vs-instrumental","note":"ambitious و responsible صح instrumental، بس equality غاية terminal، فالمجموعة مخلوطة."},{"i":3,"mis":"c3.terminal-vs-instrumental","note":"competent و self-disciplined وسيلية، بس self-esteem من الـ terminal values في قائمة الكتاب، فالمجموعة مو كلها instrumental."}],"tests":["instrumental value","terminal value","value system"]},{"n":953,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"rokeach-terminal-examples","stem":"Which of the following is a TERMINAL value that the book names as especially important for managers?","options":["competent","open-minded","equality","responsible"],"answer":2,"why":"terminal value = هدف للعمر كله. الكتاب ذكر ثلاث terminal مهمة للمديرين: sense of accomplishment, equality, self-esteem. الباقي صفات تصرّف يعني instrumental.","wrong":[{"i":0,"mis":"c3.terminal-vs-instrumental","note":"competent صفة في طريقة الشغل، يعني instrumental مو هدف للعمر."},{"i":1,"mis":"c3.terminal-vs-instrumental","note":"open-minded طريقة تفكير وتصرّف، والكتاب حطها مع الـ instrumental values."},{"i":3,"mis":"c3.terminal-vs-instrumental","note":"الكتاب حط responsible مع ambitious و self-disciplined كـ instrumental، مو terminal."}],"tests":["terminal value","instrumental value","value system"]},{"n":954,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"list","topic":"disney-socialization-values","stem":"New recruits at Disney are called 'cast members' and go to Disney University to learn the company's culture. Which four values does the book say Disney's culture emphasizes?","options":["quality, service, cleanliness, value for money","safety, courtesy, entertainment, efficiency","creativity, courtesy, entertainment, teamwork","safety, respect, cleanliness, efficiency"],"answer":1,"why":"قيم Disney الأربع: safety, courtesy, entertainment, efficiency، والجدد يتعلمونها في Disney University وبعدين في مكان شغلهم. احفظها كذا: أمان، ذوق، متعة، كفاءة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذي QSC&V حقت McDonald's ومن قيم Ray Kroc، مو Disney."},{"i":2,"mis":"gen.detail","note":"courtesy و entertainment صح، بس creativity و teamwork مو من قيم Disney في الكتاب، الإبداع أقرب لـ IDEO."},{"i":3,"mis":"gen.detail","note":"safety و efficiency صح، بس respect و cleanliness مو منها، و cleanliness من قيم McDonald's."}],"tests":["organizational socialization","disney university","values of the founder"]},{"n":955,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"scenario","topic":"socialization-program-examples","stem":"Texas A&M's 'Fish Camp' for new students, the tough training that turns military recruits into soldiers, and Disney University for new cast members are all examples of which way of transmitting organizational culture?","options":["rites of integration","the attraction–selection–attrition framework","organizational socialization","rites of enhancement"],"answer":2,"why":"الثلاثة برامج يتعلم فيها الجديد قيم المنظمة وأعرافها والتصرفات المطلوبة، وهذا تعريف organizational socialization. الكلمة المفتاح: newcomers يتعلمون the ropes أول ما يدخلون.","wrong":[{"i":0,"mis":"c3.rites-swap","note":"rites of integration زي الحفلات والطلعات تقوّي الروابط بين الموجودين، مو تعليم الجدد ثقافة المنظمة."},{"i":1,"mis":"c3.asa-framework","note":"ASA عن مين ينجذب للمنظمة ويتوظف ويبقى حسب تشابهه مع المؤسس، مو برنامج يعلّم الجدد."},{"i":3,"mis":"c3.rites-swap","note":"rites of enhancement تكريم علني للإنجاز زي حفلات الجوائز، مو تدريب الجدد."}],"tests":["organizational socialization","transmitting organizational culture"]},{"n":956,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"humane-layoffs","stem":"According to the book, which set of actions helps managers carry out a layoff humanely?","options":["showing compassion, giving short notice to limit rumors, explaining severance clearly, and helping with the job search","reducing workloads, improving communication, making managers more supportive, and offering flexible schedules","showing compassion, giving as much notice as possible, explaining severance clearly, and helping with the job search","showing compassion, giving as much notice as possible, raising survivors' pay, and moving to a four-day week"],"answer":2,"why":"الكتاب ذكر أربع طرق: compassion و empathy، أطول advance notice ممكن، معلومات واضحة عن severance benefits، ومساعدتهم يلقون وظيفة ثانية. وهذا يهم حتى اللي بقوا في الشغل (survivors).","wrong":[{"i":0,"mis":"gen.reversed","note":"الكتاب يقول as much advance notice as possible، يعني إنذار أطول مو أقصر."},{"i":1,"mis":"gen.neighbor","note":"هذي حلول الـ burnout من Gallup واللي جربها المديرين في الجائحة، مو طريقة تسريح الموظفين بإنسانية."},{"i":3,"mis":"gen.detail","note":"أول نقطتين صح، بس رفع الرواتب وأسبوع الأربع أيام مو من طرق الكتاب للتسريح، أسبوع الأربع أيام جا في قسم الـ burnout."}],"tests":["layoffs","humane layoff management","job satisfaction"]},{"n":957,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"burnout-gallup-actions","stem":"During the COVID-19 pandemic, managers tried many ways to reduce employee burnout. According to Gallup's research cited in the book, which actions matter MORE for worker engagement?","options":["four-day workweeks, flexible schedules, and limits on after-hours email","raising salaries and moving unhappy employees into higher-paying jobs","delegating work, collaborating with others, and having a voice in decisions","reducing workloads, improving communication, and making managers more supportive"],"answer":3,"why":"Gallup قال فيه أشياء أهم من اللي جربوها المديرين: reducing workloads, improving communication, equipping managers to be more supportive. تذكّرها كذا: شغل أقل، تواصل أحسن، مدير داعم.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذي فعلاً جربها بعض المديرين، بس Gallup قال فيه أفعال أهم منها."},{"i":1,"mis":"gen.neighbor","note":"رفع الرواتب من اللي جربوه المديرين، مو من الثلاث اللي Gallup قال أهم."},{"i":2,"mis":"gen.neighbor","note":"هذي طرق المدير يحسّن فيها ظروفه هو نفسه، مو أفعال Gallup لتحسين حال الموظفين."}],"tests":["burnout","attitudes in context"]},{"n":958,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"tf","topic":"burnout-managers-vs-workers","stem":"According to Gallup, as reported in the book, managers suffer burnout at lower rates than nonmanagement workers.","options":["True","False"],"answer":1,"why":"غلط. Gallup لقى الـ burnout عند المديرين أعلى من غير المديرين، لأنهم يقولون التوقعات منهم مو واضحة، والـ feedback ما يفيد، ويومهم مليان مقاطعات.","wrong":[{"i":0,"mis":"gen.reversed","note":"يمكن حسبت المدير مرتاح لأنه يقدر يفوّض الشغل، بس Gallup لقى العكس: المديرين أكثر burnout."}],"tests":["burnout"]},{"n":959,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"concept","topic":"satisfaction-and-hierarchy","stem":"How does job satisfaction usually change across the levels of an organization's hierarchy, according to the book?","options":["It tends to fall as people move up, since upper managers carry more stress.","It tends to rise as people move up, so upper managers are usually more satisfied.","It stays about the same at every level, since it depends only on personality.","It is highest among entry-level employees, since they have fewer duties."],"answer":1,"why":"الكتاب يقول levels of job satisfaction تزيد كل ما طلعت في الـ hierarchy، فالمديرين الكبار عادةً أرضى من الموظفين المبتدئين (entry-level).","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبت العلاقة: الرضا يزيد مع الصعود مو ينقص، حتى لو الضغط أكثر."},{"i":2,"mis":"gen.absolute","note":"كلمة only فخ، والكتاب يقول الـ attitudes تتأثر بظروف الشغل، والرضا يختلف حسب المستوى."},{"i":3,"mis":"gen.reversed","note":"العكس: entry-level هم الأقل رضا مقارنة بالإدارة العليا."}],"tests":["job satisfaction"]},{"n":960,"lo":"LO3-2","sec":"MGT102-CH3-S2","type":"list","topic":"conference-board-figures","stem":"The Conference Board has tracked U.S. job satisfaction since 1987. Which pairing of year and result is correct according to the book?","options":["1987 – 45%, the lowest level the survey has recorded","2019 – 61.1%, the highest level in the survey's history","2009 – 45%, the lowest level the survey has recorded","November 2020 – 45%, a sharp fall caused by the pandemic"],"answer":2,"why":"2009 وقت الركود كان 45%، أقل رقم في تاريخ المسح. باقي الأرقام: 1987 = 61.1%، و2019 = 54%، ونوفمبر 2020 = 56% (الرضا ظل عالي رغم الجائحة).","wrong":[{"i":0,"mis":"gen.detail","note":"1987 أول سنة للمسح وكان الرقم 61.1%، مو 45%."},{"i":1,"mis":"gen.detail","note":"61.1% رقم 1987، أما 2019 فكان 54%."},{"i":3,"mis":"gen.detail","note":"في الجائحة الرضا ظل عالي، 56% في نوفمبر 2020، مو هبوط."}],"tests":["job satisfaction"]},{"n":961,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"self-esteem-benefits","stem":"According to the book, why is a high level of self-esteem desirable for managers?","options":["It makes them want to be liked, so they keep good relations and help people get along.","It helps them keep high standards, push ahead on hard projects, and act on key decisions.","It makes them see outside forces as the cause of results, so they stay calm under pressure.","It makes them want to control and influence others, which matters most for top managers."],"answer":1,"why":"الكتاب أعطى ثلاث فوايد لـ high self-esteem: يحط معايير عالية ويلتزم فيها، يدفعه قدام في المشاريع الصعبة، ويعطيه الثقة ياخذ قرارات مهمة وينفذها. والناس عموماً يختارون أهداف تناسب مستوى self-esteem حقهم.","wrong":[{"i":0,"mis":"c3.affiliation-asset","note":"هذا وصف need for affiliation، والكتاب يقول ارتفاعها ممكن يضر المدير لأنه يصير همّه الناس تحبه بدل الأداء."},{"i":2,"mis":"c3.locus-reversed","note":"هذا external locus of control، والكتاب يبي المدير internal، وأصلاً ما له علاقة بـ self-esteem."},{"i":3,"mis":"c3.needs-swap","note":"هذي need for power، صح مهمة للإدارة العليا بس هي حاجة ثانية مو فايدة self-esteem."}],"tests":["self-esteem"]},{"n":962,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"harrison-traits","stem":"In the chapter's opening case, Marianne Harrison, CEO of John Hancock, moved her whole family to another country to run a bigger business, and she says her success comes from her own efforts. Which two traits does the book link to her?","options":["openness to experience and an external locus of control","conscientiousness and a high need for affiliation","negative affectivity and an internal locus of control","openness to experience and an internal locus of control"],"answer":3,"why":"الانتقال والمخاطرة = openness to experience (الكتاب قال Harrison تقبل المخاطر وتدوّر طرق جديدة تنمّي فيها الشركة). ولما تقول نجاحي من جهدي وأنا متحكمة في تصرفاتي = internal locus of control، والكتاب ذكرها بالاسم كمثال عليه.","wrong":[{"i":0,"mis":"c3.locus-reversed","note":"openness صح، بس اللي تنسب نجاحها لجهدها internal مو external."},{"i":1,"mis":"c3.big5-defs","note":"الكتاب ما وصفها بـ conscientiousness ولا affiliation، المخاطرة والانتقال علامة openness، والجهد الشخصي علامة internal locus."},{"i":2,"mis":"c3.big5-defs","note":"internal صح، بس negative affectivity يعني مشاعر سلبية وانتقاد، وهي نبرتها إيجابية وتحب التحدي."}],"tests":["openness to experience","internal locus of control"]},{"n":963,"lo":"LO3-1","sec":"MGT102-CH3-S1","type":"concept","topic":"huntington-traits","stem":"Eileen Huntington left teaching to start Huntington Learning Center with her husband. The book links three of her Big Five traits to parts of her story. Which matching is correct?","options":["new idea – conscientiousness; hard early years – openness to experience; vision for her people – agreeableness","new idea – openness to experience; hard early years – conscientiousness; vision for her people – extraversion","new idea – openness to experience; hard early years – conscientiousness; vision for her people – agreeableness","new idea – extraversion; hard early years – negative affectivity; vision for her people – agreeableness"],"answer":2,"why":"openness to experience خلّاها تشوف طريقة جديدة للتدريس الفردي وتخاطر بالمشروع، و conscientiousness شالتها في السنين الأولى الصعبة، والاهتمام بالناس (caring = مقياس لـ agreeableness) عطاها رؤية توجّه فيها موظفينها. والـ empathy تظهر بعد في استماعها لموظفينها.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبت أول اثنين: الفكرة والمخاطرة openness، والصبر على البداية الصعبة conscientiousness."},{"i":1,"mis":"c3.big5-defs","note":"caring about others مقياس لـ agreeableness، مو extraversion اللي هي الاجتماعية والحماس."},{"i":3,"mis":"c3.big5-defs","note":"الكتاب ما ذكر عنها extraversion ولا negative affectivity، الفكرة الجديدة openness والإصرار conscientiousness."}],"tests":["openness to experience","conscientiousness","agreeableness","big five personality traits"]},{"n":964,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"list","topic":"ei-across-cultures-steps","stem":"According to the book, how can a manager build emotional intelligence when working with people from other cultures?","options":["Assume people from other cultures feel different emotions, avoid personal questions, and apply your own culture's norms.","Treat unexpected behavior as a sign emotions may be shown differently, ask follow-up questions, and learn each culture's emotional norms.","Treat a lack of enthusiasm as a lack of interest, ask follow-up questions, and learn each culture's emotional norms.","Treat unexpected behavior as a sign emotions may be shown differently, ask follow-up questions, and smile often to show goodwill."],"answer":1,"why":"الكتاب أعطى ثلاث خطوات: (1) لما يجيك تصرف غير متوقع انتبه، يمكن نفس المشاعر بس معروضة بطريقة ثانية، (2) اسأل follow-up questions عشان تتأكد، (3) تعلّم emotional norms حقت كل ثقافة. المشاعر نفسها متشابهة، اللي يختلف طريقة التعبير.","wrong":[{"i":0,"mis":"c3.ei-culture","note":"الكتاب يقول feelings are similar across cultures، اللي يختلف التعبير، ولازم تسأل مو تتجنب الأسئلة."},{"i":2,"mis":"gen.partial","note":"آخر خطوتين صح، بس الكتاب قال لا تفترض قلة الحماس تعني قلة الاهتمام، لازم تتأكد من افتراضك."},{"i":3,"mis":"gen.detail","note":"أول خطوتين صح، بس معنى الابتسامة نفسه يختلف بين الثقافات، والخطوة الثالثة تعلّم emotional norms حقت كل ثقافة."}],"tests":["emotional intelligence","emotions across cultures"]},{"n":965,"lo":"LO3-4","sec":"MGT102-CH3-S3","type":"concept","topic":"smiling-across-cultures","stem":"The book compares how people use smiles in different cultures. Where is a smile more often used to cover up embarrassment or unhappiness?","options":["North America","Japan","Northern Europe","Britain"],"answer":1,"why":"في اليابان الابتسامة غالباً تغطي إحراج أو زعل. في North America يبتسمون كثير عشان يبيّنون ودّهم ونيتهم الطيبة، وفي Northern Europe الابتسامة بس للتعبير عن الفرح.","wrong":[{"i":0,"mis":"gen.detail","note":"في North America الابتسامة إشارة ودّ ونية طيبة، مو تغطية إحراج."},{"i":2,"mis":"gen.detail","note":"في Northern Europe الابتسامة محصورة للتعبير عن الفرح، وكثرة الابتسام تبان لهم غريبة."},{"i":3,"mis":"gen.neighbor","note":"البريطانيين الكتاب ذكرهم في تخفيف الحماس عشان يقدّرون self-control، مو في ابتسامة تغطي الإحراج."}],"tests":["emotional intelligence","emotions across cultures"]},{"n":966,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"people","topic":"founder-values-gates","stem":"Which company founder does the book describe as expecting staff to be creative and hard-working, while encouraging casual dress, personalized offices, and events like cookouts and picnics?","options":["Ray Kroc of McDonald's","Bill Gates of Microsoft","Walt Disney of Disney","Satya Nadella of Microsoft"],"answer":1,"why":"هذا Bill Gates، والكتاب يستخدمه مثال على values of the founder: يبي الموظف مبدع ويشتغل بجد، بس بلبس كاجوال ومكتب يخصّصه على ذوقه، وفعاليات زي الشوي والرحلات عشان يكون فرد ولاعب في الفريق بنفس الوقت.","wrong":[{"i":0,"mis":"gen.neighbor","note":"Ray Kroc هو مثال المؤسس الثاني، بس قيمه كانت خدمة العميل والنظافة (QSC&V)، مو اللبس الكاجوال."},{"i":2,"mis":"gen.neighbor","note":"قيم Walt Disney تعيش عن طريق socialization في Disney University، مو هذي الأمثلة."},{"i":3,"mis":"gen.neighbor","note":"Nadella من Microsoft بس هو CEO مو مؤسس، والكتاب ذكره في تغيير الثقافة عن طريق self-awareness و empathy."}],"tests":["values of the founder","organizational culture"]},{"n":967,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"ibm-conservative-planning","stem":"The book uses IBM as an example of planning in a conservative culture. What problem did CEO Lou Gerstner face, and what did he do?","options":["Planning was so loose that managers ignored their goals; he made every suggestion pass a formal top-down review.","Remote work had weakened collaboration; he brought thousands of remote workers back to regional offices.","HR systems were out of date; he hired the company's first senior vice president of transformation and culture.","Planning was so formal that managers spent their time defending positions; he built a campus-style headquarters to change their mind-sets."],"answer":3,"why":"في الثقافة المحافظة يكون التخطيط formal top-down. في IBM صار رسمي لدرجة المديرين يضيعون وقتهم يجهّزون عروض يدافعون فيها عن مواقفهم، فـ Gerstner بنى campus-style headquarters جديد عشان يغيّر طريقة تفكيرهم.","wrong":[{"i":0,"mis":"c3.innovative-vs-conservative","note":"قلبت المشكلة: IBM كانت رسمية زيادة مو فوضوية، و Gerstner حاول يلغي الرسمية مو يزيدها."},{"i":1,"mis":"gen.neighbor","note":"رجّع الموظفين عن بُعد للمكاتب هذي Ginni Rometty، مو Gerstner."},{"i":2,"mis":"gen.neighbor","note":"توظيف أول senior vice president of transformation and culture هذا Arvind Krishna، آخر CEO في القصة."}],"tests":["conservative culture","planning","organizational culture"]},{"n":968,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"dysfunctional-culture-boeing","stem":"The book uses Boeing as a recent example. Which statement matches how the book describes Boeing's culture and its results?","options":["a weak culture: staff shared no common values, and this led to two crashes and 346 deaths","a dysfunctional culture: a 'success at all cost' mentality led to fraud linked to one crash and 346 job losses","a conservative culture: formal top-down planning slowed safety decisions and led to two crashes","a dysfunctional culture: a 'success at all cost' mentality led to fraud linked to two crashes and 346 deaths"],"answer":3,"why":"dysfunctional culture = ثقافة تشجّع تصرفات تضر المنظمة. في Boeing عقلية 'success at all cost' المتكبرة أدت لاحتيال يمكن سبّب بشكل غير مباشر طيحتين لطيارة 737 MAX و346 وفاة، وانطرد الـ CEO. والكتاب ذكر معها Google و Facebook و Wells Fargo.","wrong":[{"i":0,"mis":"gen.neighbor","note":"weak culture يعني ما فيه التزام قوي بقيم مشتركة، و Boeing كان عندها عقلية واضحة بس مضرة، والكتاب سمّاها dysfunctional."},{"i":1,"mis":"gen.detail","note":"النوع صح بس الأرقام غلط: طيحتين و346 وفاة، مو طيحة وحدة وفقدان وظائف."},{"i":2,"mis":"c3.innovative-vs-conservative","note":"الكتاب ما وصف Boeing بالثقافة المحافظة، مثال التخطيط الرسمي البطيء هو IBM."}],"tests":["dysfunctional culture","organizational culture"]},{"n":969,"lo":"LO3-5","sec":"MGT102-CH3-S4","type":"concept","topic":"organizational-language-examples","stem":"In the book's examples of organizational language, what do McDonald's phrase 'ketchup in their blood' and IDEO's phrase 'being left-handed' mean?","options":["ketchup: still new and learning the McDonald's way; left-handed: taking the consumer's point of view","ketchup: fully socialized into the McDonald's way; left-handed: taking the consumer's point of view","ketchup: fully socialized into the McDonald's way; left-handed: breaking the company's usual rules","ketchup: working fast under heavy pressure; left-handed: working alone without a team"],"answer":1,"why":"'ketchup in their blood' = موظف تشرّب ثقافة McDonald's كلها (completely socialized). و 'being left-handed' في IDEO = تاخذ وجهة نظر المستهلك وانت تصمم. هذي slang و jargon تعطيك إشارات عن قيم المنظمة وأعرافها.","wrong":[{"i":0,"mis":"gen.reversed","note":"العكس: الكيتشب في الدم يعني تشرّب الثقافة كلها، مو لسّا جديد يتعلم."},{"i":2,"mis":"gen.keyword","note":"صح IDEO قوانينها قليلة، بس 'left-handed' معناها تشوف من عين المستهلك، مو تكسر القوانين."},{"i":3,"mis":"gen.vocab","note":"فهمت العبارات حرفياً، ومعناها في الكتاب عن التشبّع بالثقافة ووجهة نظر المستهلك."}],"tests":["organizational language","slang and jargon","organizational socialization"]}]};
